registerBank("xingfa", [
{ id: "XING-001", chapter: "正当防卫", type: "single", difficulty: 2,
  stem: "深夜，甲持刀翻墙进入乙家中意图抢劫，乙惊醒后与甲搏斗，夺下刀具将甲刺死。关于乙的行为，下列说法正确的是？",
  options: { A: "构成故意杀人罪", B: "属于防卫过当，应当负刑事责任，但应减轻处罚", C: "属于特殊防卫，不负刑事责任", D: "构成过失致人死亡罪" },
  answer: ["C"],
  analysis: "《刑法》第20条第3款规定，对正在进行行凶、杀人、抢劫、强奸、绑架以及其他严重危及人身安全的暴力犯罪采取防卫行为，造成不法侵害人伤亡的，不属于防卫过当，不负刑事责任。甲正在实施入户抢劫这一严重暴力犯罪，乙的反击属于特殊防卫，C正确。A、B、D均以乙需担责为前提，错误。",
  lawBasis: ["《刑法》第20条第3款"] },

{ id: "XING-002", chapter: "刑事责任年龄", type: "single", difficulty: 3,
  stem: "甲13周岁，以特别残忍手段故意杀害同学乙致其死亡，情节恶劣。关于甲的刑事责任，下列说法正确的是？",
  options: { A: "未满14周岁，一律不负刑事责任", B: "经最高人民检察院核准追诉的，应当负刑事责任", C: "应当负刑事责任，且必须从轻处罚", D: "是否追诉由公安机关决定" },
  answer: ["B"],
  analysis: "《刑法修正案（十一）》增设：已满12周岁不满14周岁的人，犯故意杀人、故意伤害罪，致人死亡或者以特别残忍手段致人重伤造成严重残疾，情节恶劣，经最高人民检察院核准追诉的，应当负刑事责任，B正确、A错误。对不满18周岁的人犯罪是'应当从轻或者减轻处罚'，C说'必须从轻'排除了减轻，错误。核准主体是最高人民检察院而非公安机关，D错误。",
  lawBasis: ["《刑法》第17条第3款、第4款"] },

{ id: "XING-003", chapter: "犯罪停止形态", type: "single", difficulty: 3,
  stem: "甲欲毒杀乙，将毒药放入乙的水杯。乙喝下后腹痛倒地，甲见状心生悔意，立即将乙送医，乙经抢救脱险。甲的行为属于？",
  options: { A: "犯罪未遂", B: "犯罪中止", C: "犯罪既遂", D: "不构成犯罪" },
  answer: ["B"],
  analysis: "《刑法》第24条：在犯罪过程中，自动放弃犯罪或者自动有效地防止犯罪结果发生的，是犯罪中止。甲在实行行为终了后自动采取措施有效防止了死亡结果发生，成立犯罪中止，B正确。未遂是'由于意志以外的原因'未得逞，甲是主动救助，A错误。乙未死亡，故意杀人未既遂，C错误。甲已实施杀人行为并造成损害，构成犯罪（中止犯造成损害的应当减轻处罚），D错误。",
  lawBasis: ["《刑法》第24条"] },

{ id: "XING-004", chapter: "因果关系", type: "single", difficulty: 3,
  stem: "甲持刀追杀乙，乙情急之下跳入河中躲避，因水流湍急溺水身亡。关于甲的行为与乙死亡之间的因果关系，下列说法正确的是？",
  options: { A: "乙自己跳河，属于自陷风险，因果关系中断", B: "甲的追杀行为与乙的死亡之间存在因果关系", C: "乙的死亡属于意外事件，与甲无关", D: "只有甲直接将乙推入河中才有因果关系" },
  answer: ["B"],
  analysis: "被害人在遭受紧迫不法侵害时采取的逃避行为并不异常，不能中断因果关系。乙跳河是甲持刀追杀所引起的合理避险反应，死亡结果应归属于甲的追杀行为，B正确。A项'自陷风险'适用于被害人自愿冒险的场合，乙是被迫逃生，错误。C、D否认归责，均错误。",
  lawBasis: ["刑法因果关系理论（介入因素判断规则）"] },

{ id: "XING-005", chapter: "侵犯财产罪", type: "single", difficulty: 4,
  stem: "甲谎称手机没电急需联系家人，向路人乙借用手机。乙将手机递给甲后，甲假装拨打电话，趁乙不注意突然逃走。甲的行为构成？",
  options: { A: "诈骗罪", B: "盗窃罪", C: "侵占罪", D: "抢夺罪" },
  answer: ["B"],
  analysis: "诈骗罪要求被害人基于错误认识而处分财物。乙将手机递给甲只是转移临时使用，仍处于乙的现场支配之下，并无转移所有权或占有的处分意识与处分行为；甲趁人不备携机逃离，是违反占有人意志秘密转移占有，构成盗窃罪，B正确、A错误。侵占罪以合法持有他人财物为前提且拒不退还，手机并未脱离乙的占有范围，C错误。抢夺是公然夺取，甲是趁不注意溜走，D错误。",
  lawBasis: ["《刑法》第264条"] },

{ id: "XING-006", chapter: "侵犯财产罪", type: "single", difficulty: 3,
  stem: "甲入户盗窃财物后下楼时被失主乙发现，乙上前抓捕，甲为抗拒抓捕当场对乙拳打脚踢致其轻伤后逃离。甲的行为应认定为？",
  options: { A: "盗窃罪与故意伤害罪数罪并罚", B: "盗窃罪一罪", C: "转化为抢劫罪", D: "故意伤害罪一罪" },
  answer: ["C"],
  analysis: "《刑法》第269条：犯盗窃、诈骗、抢夺罪，为窝藏赃物、抗拒抓捕或者毁灭罪证而当场使用暴力或者以暴力相威胁的，依照抢劫罪定罪处罚。甲盗窃后为抗拒抓捕当场使用暴力致人轻伤，转化为抢劫罪（且属入户情节的延续，实务中还可能认定入户抢劫），C正确，A、B、D错误。",
  lawBasis: ["《刑法》第269条"] },

{ id: "XING-007", chapter: "刑罚制度", type: "single", difficulty: 3,
  stem: "下列哪一情形成立累犯？",
  options: { A: "甲因过失致人死亡被判有期徒刑3年，释放后第2年又犯故意伤害罪", B: "乙因盗窃被判管制6个月，执行完毕后第3年又犯诈骗罪应判有期徒刑", C: "丙因抢劫被判有期徒刑5年，释放后第6年又犯故意杀人罪", D: "丁因诈骗被判有期徒刑2年，释放后第3年又犯抢劫罪应判有期徒刑" },
  answer: ["D"],
  analysis: "《刑法》第65条：被判处有期徒刑以上刑罚的犯罪分子，刑罚执行完毕或者赦免以后，在5年以内再犯应当判处有期徒刑以上刑罚之罪的，是累犯，但过失犯罪和不满18周岁的人犯罪除外。A前罪是过失犯罪，排除；B前罪是管制，未达'有期徒刑以上'，排除；C已超过5年，排除；D前后罪均为故意、均为有期徒刑以上且在5年内，成立累犯。",
  lawBasis: ["《刑法》第65条"] },

{ id: "XING-008", chapter: "量刑情节", type: "single", difficulty: 3,
  stem: "下列哪一情形不成立自首？",
  options: { A: "甲杀人后向公安机关投案并如实供述罪行", B: "乙因形迹可疑被公安人员盘问，主动如实交代了尚未被掌握的抢劫事实", C: "丙因涉嫌盗窃被逮捕后，如实供述了司法机关已经掌握的该起盗窃事实", D: "丁在父母规劝下，由父亲陪同到派出所投案并如实供述" },
  answer: ["C"],
  analysis: "自首=自动投案+如实供述自己的罪行。A是典型自首。B属于'仅因形迹可疑被盘问、教育后主动交代司法机关尚未掌握的罪行'，视为自动投案，成立自首。D经亲友规劝陪同投案，属于自动投案，成立自首。C已被采取强制措施，供述的是司法机关已掌握的本罪事实，只是坦白而非自首（如实供述司法机关尚未掌握的其他不同种罪行才以自首论），故选C。",
  lawBasis: ["《刑法》第67条", "最高法关于自首和立功的司法解释"] },

{ id: "XING-009", chapter: "共同犯罪", type: "multi", difficulty: 3,
  stem: "关于共同犯罪，下列说法正确的是？",
  options: { A: "二人以上共同过失犯罪，不以共同犯罪论处", B: "教唆不满十八周岁的人犯罪的，应当从重处罚", C: "被教唆的人没有犯被教唆的罪的，教唆者不负刑事责任", D: "对于从犯，应当从轻、减轻处罚或者免除处罚" },
  answer: ["A", "B", "D"],
  analysis: "A正确：《刑法》第25条第2款，共同过失犯罪不以共同犯罪论处，应当负刑事责任的按各自的罪分别处罚。B正确：第29条第1款后段。D正确：第27条第2款。C错误：第29条第2款，被教唆的人没有犯被教唆的罪的，对于教唆犯可以从轻或者减轻处罚，教唆犯仍需负责，并非不负刑事责任。",
  lawBasis: ["《刑法》第25条、第27条、第29条"] },

{ id: "XING-010", chapter: "刑罚制度", type: "multi", difficulty: 3,
  stem: "关于缓刑，下列说法正确的是？",
  options: { A: "对累犯不适用缓刑", B: "对符合缓刑条件的不满十八周岁的人，应当宣告缓刑", C: "被判处10年有期徒刑的犯罪分子，如有悔罪表现可以适用缓刑", D: "缓刑考验期内犯新罪的，应当撤销缓刑，数罪并罚" },
  answer: ["A", "B", "D"],
  analysis: "A正确：《刑法》第74条，对累犯和犯罪集团的首要分子不适用缓刑。B正确：第72条，对不满18周岁、怀孕的妇女和已满75周岁的人，符合条件的应当宣告缓刑。C错误：缓刑仅适用于被判处拘役、3年以下有期徒刑的犯罪分子。D正确：第77条第1款。",
  lawBasis: ["《刑法》第72条、第74条、第77条"] },

{ id: "XING-011", chapter: "贪污贿赂罪", type: "multi", difficulty: 4,
  stem: "关于受贿罪，下列说法正确的是？",
  options: { A: "国家工作人员利用职务上的便利索取他人财物的，不论是否为他人谋取利益，均构成受贿罪", B: "非法收受他人财物的，须以为他人谋取利益为要件", C: "利用本人职权或地位形成的便利条件，通过其他国家工作人员职务上的行为，为请托人谋取不正当利益并收受财物的，以受贿论处", D: "国家工作人员离职后收受财物的，一律不构成受贿罪" },
  answer: ["A", "B", "C"],
  analysis: "A正确：索贿型受贿不以'为他人谋取利益'为要件（《刑法》第385条）。B正确：收受型受贿以为他人谋取利益为要件（承诺谋利即可）。C正确：第388条斡旋受贿，注意须是'不正当利益'。D错误：司法解释规定，国家工作人员利用职务便利为请托人谋利，与请托人事先约定，在离职后收受财物的，以受贿论处。",
  lawBasis: ["《刑法》第385条、第388条"] },

{ id: "XING-012", chapter: "罪数形态", type: "multi", difficulty: 4,
  stem: "关于罪数，下列说法正确的是？",
  options: { A: "一个行为同时触犯数个罪名的，原则上从一重罪处罚", B: "绑架并杀害被绑架人的，以绑架罪和故意杀人罪数罪并罚", C: "拐卖妇女过程中奸淫被拐卖妇女的，以拐卖妇女罪和强奸罪数罪并罚", D: "盗窃仓库财物后，为毁灭罪证放火烧毁仓库危害公共安全的，以盗窃罪和放火罪数罪并罚" },
  answer: ["A", "D"],
  analysis: "A正确：想象竞合犯从一重罪处断。B错误：杀害被绑架人是绑架罪的加重处罚情节（《刑法》第239条），仍定绑架罪一罪。C错误：奸淫被拐卖的妇女是拐卖妇女罪的加重情节（第240条），定一罪。D正确：盗窃既遂后另起犯意放火灭证并危害公共安全，属于犯罪既遂后的新行为，应当数罪并罚。",
  lawBasis: ["《刑法》第239条、第240条", "罪数理论"] },

{ id: "XING-013", chapter: "危害公共安全罪", type: "indeterminate", difficulty: 4,
  stem: "关于交通肇事罪，下列说法正确的是？",
  options: { A: "交通肇事后逃逸致人死亡的，处7年以上有期徒刑", B: "肇事后为逃避法律追究，将被害人带离现场后隐藏或遗弃，致其无法得到救助而死亡的，应以故意杀人罪定罪处罚", C: "交通肇事罪的主观方面只能是过失", D: "单位主管人员指使肇事人逃逸，致被害人因得不到救助而死亡的，以交通肇事罪的共犯论处" },
  answer: ["A", "B", "C", "D"],
  analysis: "A正确：《刑法》第133条'因逃逸致人死亡的，处七年以上有期徒刑'。B正确：交通肇事司法解释第6条，此时行为性质转化为不作为的故意杀人。C正确：交通肇事罪是典型的过失犯罪。D正确：司法解释第5条第2款明确规定指使逃逸致死的以共犯论。四项均正确。",
  lawBasis: ["《刑法》第133条", "最高法交通肇事刑事案件司法解释第5、6条"] },

{ id: "XING-014", chapter: "侵犯财产罪", type: "indeterminate", difficulty: 3,
  stem: "下列哪些情形属于抢劫罪'处十年以上有期徒刑、无期徒刑或者死刑'的加重处罚情形？",
  options: { A: "入户抢劫", B: "在公共交通工具上抢劫", C: "抢劫致人重伤、死亡", D: "携带凶器抢夺" },
  answer: ["A", "B", "C"],
  analysis: "《刑法》第263条列举了八种加重情形，A（入户抢劫）、B（在公共交通工具上抢劫）、C（抢劫致人重伤、死亡）均在其中。D错误：携带凶器抢夺依照第267条第2款'依照抢劫罪定罪处罚'，只是以抢劫罪论处的拟制规定，本身并非第263条的加重处罚情形。",
  lawBasis: ["《刑法》第263条、第267条第2款"] }
,
{ id: "XING-015", chapter: "犯罪构成", type: "single", difficulty: 2,
  stem: "关于犯罪构成要件，下列说法正确的是？",
  options: { A: "任何犯罪都必须具备特定的犯罪目的", B: "犯罪客体是指犯罪所侵害的、为刑法所保护的社会关系", C: "犯罪主体只能是达到刑事责任年龄的自然人", D: "犯罪的主观方面只包括故意" },
  answer: ["B"],
  analysis: "犯罪客体即刑法所保护而为犯罪所侵害的社会关系，B正确。犯罪目的仅是部分目的犯的要件，A错误。单位也可成为犯罪主体，C错误。主观方面包括故意与过失，D错误。",
  lawBasis: ["刑法总则犯罪构成理论"] },
{ id: "XING-016", chapter: "故意与过失", type: "single", difficulty: 3,
  stem: "甲在山林中打猎，明知远处树丛有人活动仍开枪射击，希望打中猎物，结果击中他人致死。甲对该死亡结果的心理态度是？",
  options: { A: "直接故意", B: "间接故意", C: "过于自信的过失", D: "疏忽大意的过失" },
  answer: ["B"],
  analysis: "甲明知有人可能被击中而放任该结果发生，对死亡持放任态度，属间接故意，B正确。甲追求的是猎物而非他人死亡，非直接故意；行为人已预见并放任，不属过失。",
  lawBasis: ["《刑法》第14条"] },
{ id: "XING-017", chapter: "正当防卫", type: "single", difficulty: 3,
  stem: "关于正当防卫，下列说法正确的是？",
  options: { A: "对合法行为可以进行正当防卫", B: "防卫行为明显超过必要限度造成重大损害的构成防卫过当", C: "对过失犯罪不能进行正当防卫", D: "事后防卫属于正当防卫" },
  answer: ["B"],
  analysis: "防卫过当以'明显超过必要限度'且'造成重大损害'为要件，B正确。正当防卫针对的是不法侵害，合法行为不能防卫，A错误。对正在进行的过失侵害也可防卫，C错误。不法侵害已经结束的事后防卫不成立正当防卫，D错误。",
  lawBasis: ["《刑法》第20条"] },
{ id: "XING-018", chapter: "共同犯罪", type: "single", difficulty: 3,
  stem: "甲教唆乙去盗窃，乙接受教唆后却实施了抢劫。关于甲的刑事责任，下列说法正确的是？",
  options: { A: "甲对抢劫承担教唆责任", B: "甲在其教唆的盗窃范围内承担责任", C: "甲不承担任何刑事责任", D: "甲构成抢劫罪的共犯" },
  answer: ["B"],
  analysis: "实行犯的实行过限超出教唆故意范围的，教唆者仅在其教唆范围内负责。乙的抢劫超出甲教唆的盗窃故意，甲只在盗窃范围内承担教唆犯责任，B正确。",
  lawBasis: ["《刑法》第29条；共犯过限理论"] },
{ id: "XING-019", chapter: "犯罪未遂", type: "single", difficulty: 2,
  stem: "甲入室行窃，翻找财物时因被害人突然回家而慌忙逃走，未取得任何财物。甲的行为属于？",
  options: { A: "犯罪预备", B: "犯罪未遂", C: "犯罪中止", D: "不构成犯罪" },
  answer: ["B"],
  analysis: "甲已着手实行盗窃，因被害人回家这一意志以外的原因未得逞，属犯罪未遂，B正确。已着手故非预备；非自动放弃故非中止。",
  lawBasis: ["《刑法》第23条"] },
{ id: "XING-020", chapter: "累犯", type: "single", difficulty: 3,
  stem: "关于累犯，下列说法正确的是？",
  options: { A: "过失犯罪也可构成一般累犯", B: "一般累犯要求前后罪均为故意犯罪且刑罚均为有期徒刑以上", C: "累犯可以适用缓刑", D: "累犯前后罪间隔时间无限制" },
  answer: ["B"],
  analysis: "一般累犯要求前后罪都是故意犯罪、都被判处有期徒刑以上刑罚，且刑罚执行完毕或赦免后5年内再犯，B正确。过失犯罪不构成累犯，A错误。累犯不适用缓刑与假释，C错误。有5年间隔限制，D错误。",
  lawBasis: ["《刑法》第65条"] },
{ id: "XING-021", chapter: "自首与立功", type: "single", difficulty: 3,
  stem: "甲犯罪后被公安机关传唤到案，在讯问中如实供述了尚未被掌握的另一起同种罪行。关于甲的行为认定，下列正确的是？",
  options: { A: "构成一般自首", B: "构成特别自首（余罪自首）", C: "构成坦白", D: "既不构成自首也不构成坦白" },
  answer: ["B"],
  analysis: "被采取强制措施的犯罪嫌疑人如实供述司法机关还未掌握的本人其他罪行的，以自首论，即余罪自首，B正确。若供述的是已被掌握的同种罪行则属坦白。",
  lawBasis: ["《刑法》第67条第2款"] },
{ id: "XING-022", chapter: "数罪并罚", type: "single", difficulty: 3,
  stem: "甲犯A罪被判有期徒刑5年，犯B罪被判有期徒刑8年。数罪并罚时，下列决定执行的刑期符合法律规定的是？",
  options: { A: "13年", B: "10年", C: "8年", D: "20年" },
  answer: ["B"],
  analysis: "有期徒刑数罪并罚采限制加重原则，应在总和刑期以下、数刑中最高刑期以上决定，即8年以上13年以下。总和刑期未超35年的最高不超过20年。B项10年在8—13年区间内，合法。A项13年为总和刑期不可等于，C项8年为下限不可等于（须以上）。",
  lawBasis: ["《刑法》第69条"] },
{ id: "XING-023", chapter: "故意杀人罪", type: "single", difficulty: 4,
  stem: "甲以杀人故意向乙开枪，未击中乙却击中路过的丙致丙死亡。关于甲的刑事责任，下列说法正确的是？",
  options: { A: "对乙成立故意杀人未遂，对丙成立过失致人死亡", B: "根据法定符合说，甲对丙成立故意杀人既遂", C: "只成立故意杀人未遂", D: "只成立过失致人死亡罪" },
  answer: ["B"],
  analysis: "打击错误（方法错误）情形，通说采法定符合说：只要在同一犯罪构成范围内，行为人主观故意与客观结果一致，对实际死亡的丙成立故意杀人既遂，B正确。",
  lawBasis: ["《刑法》第232条；打击错误理论"] },
{ id: "XING-024", chapter: "侵犯财产罪", type: "single", difficulty: 3,
  stem: "甲将租来的汽车私自卖给不知情的乙并交付，得款后逃匿。甲的行为构成？",
  options: { A: "盗窃罪", B: "诈骗罪", C: "侵占罪", D: "合同诈骗罪或侵占罪" },
  answer: ["D"],
  analysis: "甲基于租赁合同合法占有汽车，擅自处分并逃匿，属将代为保管的他人财物非法占为己有且拒不退还，构成侵占罪；若行为发生在经济合同履行中以非法占有为目的，可能构成合同诈骗罪。D表述涵盖对合法占有物的处分定性，正确。",
  lawBasis: ["《刑法》第270条、第224条"] },
{ id: "XING-025", chapter: "贪污贿赂罪", type: "single", difficulty: 3,
  stem: "国家工作人员甲利用职务便利，为他人谋取利益，收受他人财物。甲的行为构成？",
  options: { A: "受贿罪", B: "贪污罪", C: "职务侵占罪", D: "非国家工作人员受贿罪" },
  answer: ["A"],
  analysis: "国家工作人员利用职务便利，索取或收受他人财物并为他人谋取利益的，构成受贿罪，A正确。贪污是侵吞公共财物；非国家工作人员才可能构成职务侵占罪或非国家工作人员受贿罪。",
  lawBasis: ["《刑法》第385条"] },
{ id: "XING-026", chapter: "罪刑法定原则", type: "single", difficulty: 2,
  stem: "关于罪刑法定原则，下列说法错误的是？",
  options: { A: "法无明文规定不为罪，法无明文规定不处罚", B: "禁止不利于被告人的类推解释", C: "允许有利于被告人的溯及既往", D: "允许以习惯法作为定罪依据" },
  answer: ["D"],
  analysis: "罪刑法定要求成文法定，排斥习惯法作为定罪处刑依据，D错误当选。A是罪刑法定的基本含义；B禁止类推（不利于被告）；C即从旧兼从轻，均正确。",
  lawBasis: ["《刑法》第3条"] },
{ id: "XING-027", chapter: "刑罚种类", type: "single", difficulty: 2,
  stem: "下列属于我国刑法规定的附加刑的是？",
  options: { A: "管制", B: "拘役", C: "剥夺政治权利", D: "有期徒刑" },
  answer: ["C"],
  analysis: "附加刑包括罚金、剥夺政治权利、没收财产和驱逐出境，C正确。管制、拘役、有期徒刑均为主刑。",
  lawBasis: ["《刑法》第34条"] },
{ id: "XING-028", chapter: "缓刑", type: "single", difficulty: 3,
  stem: "关于缓刑的适用，下列说法正确的是？",
  options: { A: "被判处10年有期徒刑的可以适用缓刑", B: "对累犯和犯罪集团首要分子不适用缓刑", C: "缓刑考验期一律为原判刑期", D: "缓刑只适用于过失犯罪" },
  answer: ["B"],
  analysis: "累犯和犯罪集团的首要分子不适用缓刑，B正确。缓刑仅适用于被判处拘役、3年以下有期徒刑者，A错误。考验期有法定区间而非等于原判刑期，C错误。缓刑不限于过失犯罪，D错误。",
  lawBasis: ["《刑法》第72条、第74条"] },
{ id: "XING-029", chapter: "危害公共安全罪", type: "single", difficulty: 3,
  stem: "甲醉酒驾驶机动车在道路上行驶，尚未造成事故。甲的行为构成？",
  options: { A: "交通肇事罪", B: "危险驾驶罪", C: "以危险方法危害公共安全罪", D: "不构成犯罪" },
  answer: ["B"],
  analysis: "在道路上醉酒驾驶机动车的，构成危险驾驶罪，属抽象危险犯，无需实际发生事故，B正确。交通肇事罪要求发生重大事故，A错误。",
  lawBasis: ["《刑法》第133条之一"] },
{ id: "XING-030", chapter: "刑法效力", type: "single", difficulty: 2,
  stem: "关于刑法的溯及力，我国采取的原则是？",
  options: { A: "从新原则", B: "从旧原则", C: "从新兼从轻原则", D: "从旧兼从轻原则" },
  answer: ["D"],
  analysis: "我国刑法采从旧兼从轻原则：原则上适用行为时的旧法，但新法不认为是犯罪或处刑较轻的适用新法，D正确。",
  lawBasis: ["《刑法》第12条"] },
{ id: "XING-031", chapter: "正当防卫", type: "multi", difficulty: 3,
  stem: "关于特殊防卫（无过当防卫），下列说法正确的有？",
  options: { A: "适用于正在进行的行凶、杀人、抢劫、强奸、绑架等严重危及人身安全的暴力犯罪", B: "造成不法侵害人伤亡的不属于防卫过当", C: "对一般的轻微侵害也可实行特殊防卫", D: "特殊防卫不负刑事责任" },
  answer: ["A","B","D"],
  analysis: "特殊防卫针对严重危及人身安全的特定暴力犯罪（A），造成侵害人伤亡不属防卫过当（B）、不负刑事责任（D）。C错误：特殊防卫仅限法定严重暴力犯罪，一般轻微侵害不适用。",
  lawBasis: ["《刑法》第20条第3款"] },
{ id: "XING-032", chapter: "共同犯罪", type: "multi", difficulty: 4,
  stem: "关于共同犯罪，下列说法正确的有？",
  options: { A: "共同犯罪是指二人以上共同故意犯罪", B: "二人以上共同过失犯罪不以共同犯罪论处", C: "主犯是组织、领导犯罪集团或在共同犯罪中起主要作用的人", D: "从犯应当从轻、减轻或免除处罚" },
  answer: ["A","B","C","D"],
  analysis: "A为共同犯罪定义；B正确，共同过失不成立共犯，分别定罪；C为主犯定义；D正确，对从犯应当（而非可以）从轻、减轻或免除处罚。四项均正确。",
  lawBasis: ["《刑法》第25条、第26条、第27条"] },
{ id: "XING-033", chapter: "犯罪停止形态", type: "multi", difficulty: 3,
  stem: "下列情形中，成立犯罪中止的有？",
  options: { A: "甲下毒后后悔，主动送被害人就医脱险", B: "乙盗窃时听到警笛声害怕而逃走", C: "丙抢劫时见被害人是熟人遂放弃", D: "丁强奸时因被害人反抗激烈无法得逞而离开" },
  answer: ["A","C"],
  analysis: "中止要求'自动'放弃或有效防止结果。A自动有效防止结果，C出于自身意愿自动放弃，均成立中止。B因外界警笛（意志以外原因）逃走属未遂；D因反抗无法得逞属未遂，均非中止。",
  lawBasis: ["《刑法》第24条"] },
{ id: "XING-034", chapter: "罪数形态", type: "multi", difficulty: 4,
  stem: "关于罪数形态，下列说法正确的有？",
  options: { A: "想象竞合犯从一重罪处断", B: "牵连犯一般从一重罪处断", C: "连续犯是基于同一或概括故意连续实施数个独立的同种犯罪", D: "结果加重犯应数罪并罚" },
  answer: ["A","B","C"],
  analysis: "想象竞合从一重（A）、牵连犯原则上从一重（B）、连续犯定义（C）均正确。结果加重犯是一罪，按加重的法定刑处罚，不并罚，D错误。",
  lawBasis: ["刑法罪数理论"] },
{ id: "XING-035", chapter: "刑事责任年龄", type: "multi", difficulty: 3,
  stem: "关于刑事责任年龄，下列说法正确的有？",
  options: { A: "不满12周岁的人一律不负刑事责任", B: "已满14周岁不满16周岁的人对故意杀人、抢劫等八种犯罪负刑事责任", C: "已满16周岁的人犯罪应负刑事责任", D: "已满75周岁的人故意犯罪一律不负刑事责任" },
  answer: ["A","B","C"],
  analysis: "A、B、C均正确。D错误：已满75周岁的人故意犯罪可以从轻或减轻处罚、过失犯罪应当从轻或减轻，但并非不负刑事责任。",
  lawBasis: ["《刑法》第17条、第17条之一"] },
{ id: "XING-036", chapter: "紧急避险", type: "multi", difficulty: 3,
  stem: "关于紧急避险，下列说法正确的有？",
  options: { A: "为避免正在发生的危险不得已损害另一较小合法权益", B: "避险行为造成的损害不能超过所避免的损害", C: "职务上、业务上负有特定责任的人不适用避险的规定", D: "紧急避险可以针对第三人合法利益实施" },
  answer: ["A","B","C","D"],
  analysis: "紧急避险须迫不得已（A）、损害小于所避免损害（B）、有特定责任者遇本人危险不能避险（C）、避险损害的是第三人合法利益（D）。四项均正确。",
  lawBasis: ["《刑法》第21条"] },
{ id: "XING-037", chapter: "毒品犯罪", type: "single", difficulty: 3,
  stem: "甲明知是毒品而为他人代为运输，数量较大。甲的行为构成？",
  options: { A: "非法持有毒品罪", B: "运输毒品罪", C: "窝藏毒品罪", D: "不构成犯罪" },
  answer: ["B"],
  analysis: "明知是毒品而运输的，无论数量多少均构成运输毒品罪，B正确。非法持有是无法查明走私、贩卖、运输目的时的兜底认定。",
  lawBasis: ["《刑法》第347条"] },
{ id: "XING-038", chapter: "妨害社会管理秩序罪", type: "single", difficulty: 3,
  stem: "甲伪造居民身份证出售牟利。甲的行为构成？",
  options: { A: "伪造、变造、买卖国家机关公文、证件、印章罪", B: "伪造、变造、买卖身份证件罪", C: "诈骗罪", D: "招摇撞骗罪" },
  answer: ["B"],
  analysis: "伪造、变造、买卖居民身份证、护照等身份证件的，构成伪造、变造、买卖身份证件罪，B正确。身份证件有专门罪名，不再以公文证件罪论。",
  lawBasis: ["《刑法》第280条之一"] },
{ id: "XING-039", chapter: "刑罚裁量", type: "single", difficulty: 2,
  stem: "关于量刑情节，下列说法正确的是？",
  options: { A: "从重处罚可以突破法定最高刑", B: "减轻处罚是在法定刑以下判处刑罚", C: "从轻处罚是在法定刑以下判处刑罚", D: "免除处罚意味着不构成犯罪" },
  answer: ["B"],
  analysis: "减轻处罚指在法定刑以下判处刑罚，B正确。从重、从轻均在法定刑幅度内进行，A、C错误。免除处罚是定罪但不判刑，仍构成犯罪，D错误。",
  lawBasis: ["《刑法》第62条、第63条"] },
{ id: "XING-040", chapter: "渎职罪", type: "single", difficulty: 3,
  stem: "国家机关工作人员甲严重不负责任，不履行职责，致使公共财产遭受重大损失。甲的行为构成？",
  options: { A: "滥用职权罪", B: "玩忽职守罪", C: "受贿罪", D: "徇私枉法罪" },
  answer: ["B"],
  analysis: "国家机关工作人员严重不负责任、不履行或不正确履行职责，致使公共财产、国家和人民利益遭受重大损失的，构成玩忽职守罪，B正确。滥用职权是超越职权或违规行使职权。",
  lawBasis: ["《刑法》第397条"] }
,
{ id: "XING-041", chapter: "正当防卫", type: "indeterminate", difficulty: 4,
  stem: "关于正当防卫与紧急避险的区别，下列说法正确的有？",
  options: { A: "正当防卫针对不法侵害人本人，紧急避险损害的是第三人合法利益", B: "紧急避险要求不得已，正当防卫不要求是唯一手段", C: "二者都要求面临正在发生的危险或不法侵害", D: "紧急避险造成的损害不能超过所避免的损害，正当防卫无此严格限制" },
  answer: ["A","B","C","D"],
  analysis: "正当防卫指向侵害人本人，避险损害第三人（A）；避险须迫不得已、防卫不要求唯一手段（B）；二者都以现实紧迫的危险/侵害为前提（C）；避险损害须小于所避免损害，防卫只要求不明显超过必要限度（D）。四项均正确。",
  lawBasis: ["《刑法》第20条、第21条"] },
{ id: "XING-042", chapter: "犯罪构成", type: "indeterminate", difficulty: 4,
  stem: "关于犯罪主观方面，下列说法正确的有？",
  options: { A: "直接故意是明知自己的行为会发生危害结果并希望其发生", B: "间接故意是明知可能发生并放任其发生", C: "过于自信的过失是已经预见但轻信能够避免", D: "疏忽大意的过失是应当预见因疏忽而没有预见" },
  answer: ["A","B","C","D"],
  analysis: "直接故意（希望，A）、间接故意（放任，B）、过于自信的过失（已预见轻信能避免，C）、疏忽大意的过失（应预见而未预见，D）。四项定义均正确。",
  lawBasis: ["《刑法》第14条、第15条"] },
{ id: "XING-043", chapter: "拓展题库", type: "single", difficulty: 2,
  stem: "甲15周岁，实施了下列行为，其中应当负刑事责任的是？",
  options: { A: "盗窃他人财物价值10万元", B: "贩卖毒品", C: "绑架他人索要财物（未杀害、伤害被绑架人）", D: "走私毒品" },
  answer: ["B"],
  analysis: "A：错误。已满14不满16周岁仅对八种犯罪负刑事责任，盗窃不在其列。 B：正确。已满14周岁不满16周岁的人，犯故意杀人、故意伤害致人重伤或者死亡、强奸、抢劫、贩卖毒品、放火、爆炸、投放危险物质罪的，应当负刑事责任。 C：错误。绑架罪不在八种犯罪之列；但绑架中杀害被绑架人的按故意杀人追究。 D：错误。八种罪中只有'贩卖毒品'，走私、运输、制造毒品行为不在其列。 【考点】刑事责任年龄的阶梯：已满16周岁的人犯罪，应当负刑事责任；已满14不满16周岁的人，犯故意杀人、故意伤害致人重伤或者死亡、强奸、抢劫、贩卖毒品、放火、爆炸、投放危险物质罪的，应当负刑事责任（注意是八种'犯罪行为'而非罪名，如绑架中杀害被绑架人的定故意杀人罪）；已满12不满14周岁的人，犯故意杀人、故意伤害罪，致人死亡或者以特别残忍手段致人重伤造成严重残疾，情节恶劣，经最高人民检察院核准追诉的，应当负刑事责任。已满14不满18周岁的人犯罪，应当从轻或者减轻处罚。因不满16周岁不予刑事处罚的，责令其父母或者其他监护人加以管教，必要时依法进行专门矫治教育。" },
{ id: "XING-044", chapter: "拓展题库", type: "single", difficulty: 3,
  stem: "甲欲毒死乙，将毒药投入乙的水杯。乙喝水前，甲后悔，将水杯打翻，乙未受任何伤害。甲的行为属于？",
  options: { A: "犯罪预备", B: "犯罪未遂", C: "犯罪中止", D: "不构成犯罪" },
  answer: ["C"],
  analysis: "A：错误。投毒行为已经着手实行犯罪，超出预备阶段。 B：错误。未遂是因意志以外的原因未得逞；甲是自动放弃并有效防止结果发生。 C：正确。在犯罪过程中，自动有效地防止犯罪结果发生的，是犯罪中止。没有造成损害的，应当免除处罚。 D：错误。甲已实施故意杀人的实行行为，构成故意杀人罪（中止），只是没有造成损害应当免除处罚。 【考点】犯罪中止的成立条件：时间性（在犯罪过程中，包括预备、实行阶段及实行终了后结果发生前）；自动性（出于本人意志放弃犯罪，'能达目的而不欲'）；有效性（彻底放弃犯罪或有效防止犯罪结果发生）。实行终了后的中止必须采取积极措施有效防止结果发生。处罚：对于中止犯，没有造成损害的，应当免除处罚；造成损害的，应当减轻处罚。与未遂的区分口诀：'能达目的而不欲'是中止，'欲达目的而不能'是未遂。若甲虽尽力抢救但被害人仍死亡的，不成立中止，成立故意杀人既遂。" },
{ id: "XING-045", chapter: "拓展题库", type: "single", difficulty: 3,
  stem: "甲深夜潜入乙家行窃，被乙发现后为抗拒抓捕当场对乙使用暴力致其轻伤。甲的行为应定性为？",
  options: { A: "盗窃罪与故意伤害罪数罪并罚", B: "抢劫罪", C: "盗窃罪", D: "故意伤害罪" },
  answer: ["B"],
  analysis: "A：错误。为抗拒抓捕当场使用暴力，法律拟制为转化型抢劫，以抢劫罪一罪论处。 B：正确。犯盗窃、诈骗、抢夺罪，为窝藏赃物、抗拒抓捕或者毁灭罪证而当场使用暴力或者以暴力相威胁的，依照抢劫罪定罪处罚（转化型抢劫）。且系入户盗窃后在户内转化，构成入户抢劫。 C：错误。当场使用暴力抗拒抓捕已使行为性质转化。 D：错误。暴力行为被抢劫罪吸收评价，轻伤不另定故意伤害罪。 【考点】转化型抢劫（刑法第269条）的条件：前提行为是犯盗窃、诈骗、抢夺罪（司法解释明确不要求达到'数额较大'的既遂标准，但应有相当危害）；目的是窝藏赃物、抗拒抓捕或者毁灭罪证；当场使用暴力或者以暴力相威胁（'当场'包括现场及被追捕的延续过程）。在户内盗窃被发现后转化使用暴力的，认定为'入户抢劫'，适用加重法定刑（十年以上）。注意：携带凶器抢夺的，直接依照抢劫罪定罪处罚（第267条第2款），无需暴力转化条件。" },
{ id: "XING-046", chapter: "拓展题库", type: "single", difficulty: 4,
  stem: "甲意图杀乙，向乙开枪，因手法不准打死了站在乙身旁的丙。关于甲的刑事责任，按照法定符合说，下列说法正确的是？",
  options: { A: "对乙构成故意杀人未遂，对丙构成过失致人死亡，数罪并罚", B: "对丙构成故意杀人既遂（对乙的未遂被吸收），以故意杀人罪既遂一罪论处", C: "意外事件，不负刑事责任", D: "对丙仅构成故意伤害罪" },
  answer: ["B"],
  analysis: "A：错误。这是具体符合说的结论（且通常也认为想象竞合从一重），并非法定符合说。 B：正确。法定符合说认为，甲意图杀'人'而实际杀死了'人'，在故意杀人罪的构成要件范围内主客观一致，对丙成立故意杀人既遂；对乙未遂与对丙既遂系一行为，从一重以既遂论。 C：错误。打击错误不影响故意犯罪的成立，绝非意外事件。 D：错误。甲有杀人故意且造成死亡结果，不能降格为伤害。 【考点】打击错误（方法错误）指行为人对侵害对象没有认识错误，但因行为本身的差误导致实际侵害对象与意图对象不一致。法定符合说（通说与实务立场）：只要行为人认识的事实与实际发生的事实在同一犯罪构成（法定构成要件）范围内一致，即成立故意的既遂犯——意图杀人而杀死了人，成立故意杀人既遂。具体符合说：对意图对象成立未遂、对实际对象成立过失犯罪，想象竞合从一重处罚。对象错误（误把丙当作乙杀死）在同一构成要件内，两说结论一致，均成立故意杀人既遂。考试中注意题干指定的学说立场。" },
{ id: "XING-047", chapter: "拓展题库", type: "single", difficulty: 3,
  stem: "甲被乙持刀追杀，情急之下夺过路人丙的自行车逃跑，自行车损坏（损失800元）。甲的行为属于？",
  options: { A: "紧急避险", B: "正当防卫", C: "抢夺罪", D: "故意毁坏财物罪" },
  answer: ["A"],
  analysis: "A：正确。为了使本人的人身权利免受正在发生的危险，不得已损害第三人较小的合法权益，符合紧急避险的成立条件，不负刑事责任。 B：错误。正当防卫针对不法侵害人本人实施；甲损害的是无辜第三人丙的利益。 C：错误。甲无非法占有目的，且行为符合紧急避险，阻却违法性。 D：错误。紧急避险造成的损害由危险引起，且未超过必要限度，不构成犯罪。 【考点】紧急避险的成立条件：存在现实危险（自然灾害、动物侵袭、不法侵害等均可成为险源）；危险正在发生；为了使国家、公共利益、本人或者他人的合法权益免受危险；不得已而采取（补充性——没有其他合理选择）；没有超过必要限度造成不应有的损害（所保全利益须大于所损害利益，生命权不得通过牺牲他人生命来保全）。避险过当应当负刑事责任，但是应当减轻或者免除处罚。关于避免本人危险的规定，不适用于职务上、业务上负有特定责任的人。与正当防卫的核心区别：防卫针对不法侵害人，避险损害无辜第三人利益。" },
{ id: "XING-048", chapter: "拓展题库", type: "single", difficulty: 3,
  stem: "甲深夜遭乙徒手殴打，甲掏出随身水果刀将乙刺成重伤。关于甲的行为，下列说法正确的是？",
  options: { A: "构成故意伤害罪", B: "若未明显超过必要限度，属于正当防卫，不负刑事责任", C: "徒手殴打属于'行凶'，甲可行使特殊防卫权，任何后果均不担责", D: "甲使用刀具即属防卫过当" },
  answer: ["B"],
  analysis: "A：不必然。需判断是否防卫过当；若明显超过必要限度造成重大损害才构成犯罪。 B：正确。正当防卫是否过当，以是否'明显超过必要限度造成重大损害'为标准，面对暴力殴打持刀反击不必然过当，应结合侵害强度、紧迫程度综合判断。 C：错误。特殊防卫针对行凶、杀人、抢劫、强奸、绑架以及其他严重危及人身安全的暴力犯罪；一般徒手殴打通常不属于'行凶'。 D：错误。防卫工具不对等不等于过当，判断标准是必要限度与损害的综合衡量。 【考点】正当防卫的成立条件：起因（存在现实的不法侵害）、时间（不法侵害正在进行）、意思（具有防卫意识）、对象（针对不法侵害人本人）、限度（没有明显超过必要限度造成重大损害）。防卫过当的，应当负刑事责任，但是应当减轻或者免除处罚。特殊防卫（无限防卫权）：对正在进行行凶、杀人、抢劫、强奸、绑架以及其他严重危及人身安全的暴力犯罪，采取防卫行为，造成不法侵害人伤亡的，不属于防卫过当。'行凶'指使用致命性凶器或虽难以确定具体故意但足以严重危及人身安全的暴力攻击。判断限度应立足防卫人当时所处情境，不能事后以冷静旁观者标准苛求。" },
{ id: "XING-049", chapter: "拓展题库", type: "multi", difficulty: 3,
  stem: "关于罪刑法定原则，下列说法正确的有？",
  options: { A: "法律明文规定为犯罪行为的，依照法律定罪处刑；法律没有明文规定为犯罪行为的，不得定罪处刑", B: "禁止不利于行为人的溯及既往", C: "禁止不利于行为人的类推解释", D: "司法解释可以创设新的犯罪" },
  answer: ["A", "B", "C"],
  analysis: "A：应选。这是刑法第3条对罪刑法定原则的表述。 B：应选。罪刑法定派生规则之一：刑法适用从旧兼从轻，新法原则上不溯及既往，但新法不认为是犯罪或处刑较轻的除外。 C：应选。类推解释被罪刑法定原则禁止（有利于行为人的类推除外），扩大解释在文义射程内则被允许。 D：不应选。犯罪与刑罚只能由立法机关以法律规定（法律主义/成文法主义），司法解释只能在法律文义范围内解释。 【考点】罪刑法定原则的基本内容：法律主义（成文法，行政法规、习惯法不能创设犯罪）；禁止溯及既往（从旧兼从轻）；禁止类推解释（不利于行为人的类推）；禁止绝对不定期刑；明确性原则；禁止处罚不当罚的行为；禁止残虐刑罚。扩大解释与类推解释的区分：扩大解释未超出刑法用语可能具有的含义（文义射程），为公民预测可能性所容纳，被允许；类推解释超出文义射程，将相似事项比照处理，被禁止。从旧兼从轻：行为时法律不认为是犯罪的适用旧法；行为时法认为是犯罪但新法不认为是犯罪或者处刑较轻的，适用新法。" },
{ id: "XING-050", chapter: "拓展题库", type: "single", difficulty: 3,
  stem: "甲将被害人乙推入湖中意图淹死，见乙挣扎呼救而不救助，乙溺亡。甲对乙负有救助义务的来源是？",
  options: { A: "法律明文规定的义务", B: "先行行为引起的义务", C: "职务或业务要求的义务", D: "合同约定的义务" },
  answer: ["B"],
  analysis: "A：错误。甲乙间无法定的扶养救助关系。 B：正确。甲将乙推入湖中的先行行为使乙的生命处于危险状态，产生防止结果发生的作为义务。本案实际是作为的故意杀人（推入行为本身），先行行为义务理论用于分析后续不救助情节。 C：错误。甲并非负有救助职责的职务、业务人员。 D：错误。双方无合同关系。 【考点】不作为犯的作为义务来源（形式四分说）：法律明文规定的义务（如父母对子女的抚养义务、警察的救助职责）；职务或者业务要求的义务（如值班医生、游泳教练）；法律行为（合同、自愿接受行为）引起的义务（如保姆看护婴儿）；先行行为引起的义务（自己的行为使法益处于危险状态时负有防止危险现实化的义务）。不作为犯罪的成立还要求：有能力履行而不履行；不作为与结果之间具有因果关系；与作为具有等价性（不真正不作为犯）。注意正当防卫等合法行为原则上不产生作为义务，过失犯罪行为和意外行为可以成为先行行为。" },
{ id: "XING-051", chapter: "拓展题库", type: "single", difficulty: 2,
  stem: "甲以为自己盗窃的是普通财物，实际上箱内是枪支。关于甲的责任，下列说法正确的是？",
  options: { A: "构成盗窃枪支罪", B: "构成盗窃罪", C: "构成盗窃枪支罪与盗窃罪，数罪并罚", D: "无罪" },
  answer: ["B"],
  analysis: "A：错误。甲没有盗窃枪支的故意，对枪支缺乏认识，不成立盗窃枪支罪的故意犯。 B：正确。抽象的事实认识错误中，主客观一致的范围内定罪：甲有盗窃普通财物的故意并实施了盗窃行为，在盗窃罪的范围内主客观统一，成立盗窃罪。 C：错误。一个行为不能重复评价为两个既遂罪并罚。 D：错误。甲具备盗窃罪的全部构成要件。 【考点】抽象的事实认识错误（不同犯罪构成间的错误）的处理原则：在主客观相统一的范围内认定犯罪，即在轻罪（重合的限度）范围内成立故意犯罪。行为人意图犯轻罪、实际触犯重罪的（以为盗窃普通财物实为枪支），就重罪缺乏故意，在两罪构成要件重合的限度内（普通财物与枪支重合于'财物'）成立轻罪（盗窃罪）既遂。意图犯重罪、客观实现轻罪的，视具体情况成立重罪未遂与轻罪既遂的想象竞合。同一构成要件内的错误（具体的事实认识错误，如对象错误、打击错误）依法定符合说不阻却故意既遂。" },
{ id: "XING-052", chapter: "拓展题库", type: "multi", difficulty: 4,
  stem: "甲教唆乙杀丙，乙持刀前往丙家途中被警察查获。关于甲、乙的责任，下列说法正确的有？",
  options: { A: "乙成立故意杀人罪的犯罪预备", B: "甲作为教唆犯，按照其在共同犯罪中所起的作用处罚", C: "如果乙根本未实施任何犯罪行为，甲成立教唆未遂，可以从轻或者减轻处罚", D: "教唆不满十八周岁的人犯罪的，应当从重处罚" },
  answer: ["A", "B", "C", "D"],
  analysis: "A：应选。乙为杀人准备工具、制造条件（携刀前往途中），尚未着手实行即被制止，属于犯罪预备。 B：应选。教唆他人犯罪的，应当按照他在共同犯罪中所起的作用处罚。乙已开始实施犯罪（预备），甲乙成立共犯，甲对预备形态负责。 C：应选。被教唆的人没有犯被教唆的罪的，对于教唆犯，可以从轻或者减轻处罚（教唆未遂，刑法第29条第2款）。 D：应选。刑法第29条第1款后段明确规定。 【考点】教唆犯的处罚规则：教唆他人犯罪的，按照其在共同犯罪中所起的作用处罚（起主要作用按主犯处理，次要作用按从犯处理）；教唆不满十八周岁的人犯罪的，应当从重处罚；被教唆的人没有犯被教唆的罪的（教唆未遂——被教唆人拒绝、未产生犯意、犯了其他罪等），对于教唆犯可以从轻或者减轻处罚。共同犯罪的停止形态从属于实行行为：实行犯着手后未得逞为未遂，共犯均对未遂负责；实行犯处于预备阶段被制止的，共犯对预备形态负责。对于预备犯，可以比照既遂犯从轻、减轻处罚或者免除处罚。间接正犯：利用无责任能力人、不知情者实施犯罪的，利用者按单独正犯处理。" },
{ id: "XING-053", chapter: "拓展题库", type: "single", difficulty: 3,
  stem: "甲、乙共谋入室盗窃，甲入室行窃，乙在门外望风。得手后二人平分赃物。关于乙的责任，下列说法正确的是？",
  options: { A: "乙仅构成掩饰、隐瞒犯罪所得罪", B: "乙与甲构成盗窃罪的共同犯罪", C: "乙未入室，不构成犯罪", D: "乙构成盗窃罪的教唆犯" },
  answer: ["B"],
  analysis: "A：错误。乙事前通谋并参与实施（望风），是盗窃罪的共犯，不是事后的赃物犯罪。 B：正确。二人以上共同故意犯罪构成共同犯罪；望风是分工之一，乙对全部盗窃结果承担责任。 C：错误。共同犯罪不要求每人都实施实行行为，帮助、望风行为亦纳入共同犯罪。 D：错误。乙没有教唆行为，其望风属于帮助或分担实行的行为，一般认定为从犯（帮助犯）或共同实行。 【考点】共同犯罪是指二人以上共同故意犯罪，要求有共同的犯罪故意和共同的犯罪行为（包括实行、组织、教唆、帮助行为）。'部分实行全部责任'原则：各共犯人对共同故意范围内的全部犯罪结果承担责任。主从犯划分：在共同犯罪中起主要作用的是主犯；起次要或者辅助作用的是从犯，对于从犯应当从轻、减轻处罚或者免除处罚。事前通谋的事后行为（如事前约定的窝藏、销赃）以共同犯罪论处；无事前通谋、事后帮助窝藏赃物的，单独构成掩饰、隐瞒犯罪所得、犯罪所得收益罪。共同犯罪与承继共犯、片面共犯等特殊形态注意区分。" },
{ id: "XING-054", chapter: "拓展题库", type: "single", difficulty: 4,
  stem: "甲、乙共谋殴打丙（故意伤害），殴打过程中甲突起杀意，掏出匕首将丙刺死，乙对此毫不知情且未参与刺杀。关于乙的责任，下列说法正确的是？",
  options: { A: "乙对丙的死亡承担故意杀人罪的共犯责任", B: "乙在故意伤害的范围内承担责任；若伤害行为与死亡有因果关系，可能承担故意伤害（致死）的责任，但不承担故意杀人罪责任", C: "乙无罪", D: "甲、乙均构成故意杀人罪" },
  answer: ["B"],
  analysis: "A：错误。甲的杀人行为属于实行过限，超出共同故意范围，乙不对过限行为负责。 B：正确。共同犯罪以共同故意为限，甲的临时起意杀人系实行过限，由甲单独负故意杀人罪责；乙仅在共谋的伤害范围内负责。 C：错误。乙参与共谋并实施了殴打，至少构成故意伤害罪。 D：错误。乙无杀人故意，不能对甲的过限行为承担杀人责任。 【考点】实行过限（共同犯罪中的过剩行为）指实行犯实施了超出共同犯罪故意范围的行为。处理规则：过限行为由实行者单独承担刑事责任，其他共犯人仅在共同故意范围内负责。判断关键是过限行为是否超出共谋范围以及其他共犯人是否明知并容认。常见情形：共谋盗窃，一人转化抢劫（其他人不知情的不担抢劫责任）；共谋伤害，一人起意杀人。注意故意伤害致死是结果加重犯：共同伤害行为与死亡结果有因果关系时，各共同伤害人均可能对致死结果负责（部分实行全部责任），但杀人故意的评价仅归于起杀意者。" },
{ id: "XING-055", chapter: "拓展题库", type: "single", difficulty: 3,
  stem: "下列关于自首的说法，正确的是？",
  options: { A: "犯罪后自动投案，如实供述自己的罪行的，是自首；对于自首的犯罪分子，可以从轻或者减轻处罚", B: "自首的必须减轻处罚", C: "被采取强制措施的犯罪嫌疑人如实供述司法机关已掌握的本人罪行的，以自首论", D: "自动投案后又翻供的，仍认定为自首" },
  answer: ["A"],
  analysis: "A：正确。刑法第67条第1款：自动投案+如实供述=一般自首；可以从轻或减轻处罚，犯罪较轻的可以免除处罚。 B：错误。自首是'可以'型从宽情节，不是'应当'。 C：错误。准自首（余罪自首）要求供述的是司法机关'还未掌握的本人其他罪行'。 D：错误。如实供述后又翻供的，不能认定为自首；但在一审判决前又能如实供述的，应当认定为自首。 【考点】自首分为一般自首与准自首。一般自首=自动投案+如实供述自己的罪行。自动投案的认定较宽：犯罪后主动报案、委托他人代为投案、亲友规劝陪同投案、'送子归案'等均可认定；仅因形迹可疑被盘问、教育后主动交代罪行的，视为自动投案。准自首：被采取强制措施的犯罪嫌疑人、被告人和正在服刑的罪犯，如实供述司法机关还未掌握的本人其他罪行的，以自首论。处罚：可以从轻或者减轻处罚；犯罪较轻的，可以免除处罚。坦白：犯罪嫌疑人虽不具有自首情节，但是如实供述自己罪行的，可以从轻处罚；因其如实供述避免特别严重后果发生的，可以减轻处罚。" },
{ id: "XING-056", chapter: "拓展题库", type: "single", difficulty: 2,
  stem: "甲犯抢劫罪被判处有期徒刑10年，服刑期间又故意伤害他人被判5年。对甲应如何处理？",
  options: { A: "前后刑期相加，执行15年", B: "将前罪没有执行完毕的刑罚和后罪所判处的刑罚，依照数罪并罚规定决定执行的刑罚（先减后并）", C: "仅执行较重的刑罚", D: "以新罪的刑期为准" },
  answer: ["B"],
  analysis: "A：错误。刑罚执行期间又犯新罪的，采用'先减后并'方法，不是简单相加。 B：正确。判决宣告以后、刑罚执行完毕以前，被判刑的犯罪分子又犯罪的，应当对新犯的罪作出判决，把前罪没有执行的刑罚和后罪所判处的刑罚，依照第69条的规定，决定执行的刑罚。 C：错误。有期徒刑并罚采限制加重原则，不是吸收原则。 D：错误。前罪未执行完的刑期须并入计算。 【考点】数罪并罚的三种情形：判决宣告前一人犯数罪的，直接依第69条并罚（限制加重为主：总和刑期以下、数刑中最高刑期以上酌情决定，有期徒刑总和不满35年的最高不超过20年、35年以上的不超过25年）；判决宣告后刑罚执行完毕前发现漏罪的，'先并后减'（将漏罪与原判决的罪并罚，已执行刑期计算在新判决决定的刑期以内）；刑罚执行期间又犯新罪的，'先减后并'（前罪未执行的刑罚与新罪刑罚并罚）。先减后并的实际执行刑期可能超过先并后减，体现对再犯的从严。死刑、无期徒刑采吸收原则；附加刑仍须执行，同种附加刑合并执行。" },
{ id: "XING-057", chapter: "拓展题库", type: "single", difficulty: 3,
  stem: "甲因盗窃罪被判有期徒刑3年，刑满释放后第4年又犯应当判处有期徒刑的诈骗罪。甲是否构成累犯？",
  options: { A: "构成一般累犯，应当从重处罚", B: "不构成累犯，因间隔超过3年", C: "构成特别累犯", D: "可以从重处罚" },
  answer: ["A"],
  analysis: "A：正确。被判处有期徒刑以上刑罚的犯罪分子，刑罚执行完毕或者赦免以后，在5年以内再犯应当判处有期徒刑以上刑罚之罪的，是累犯，应当从重处罚。前后罪均为故意犯罪，间隔4年在5年之内。 B：错误。一般累犯的时间条件是刑罚执行完毕或赦免后5年以内。 C：错误。特别累犯限于危害国家安全犯罪、恐怖活动犯罪、黑社会性质的组织犯罪之间。 D：错误。累犯是'应当'从重处罚，且不适用缓刑、不得假释。 【考点】一般累犯的成立条件：前罪与后罪都是故意犯罪；前罪被判处有期徒刑以上刑罚，后罪应当判处有期徒刑以上刑罚；后罪发生在前罪刑罚执行完毕或者赦免以后5年以内（被假释的犯罪分子，从假释期满之日起计算）。不满十八周岁的人犯罪的，不构成累犯。特别累犯：危害国家安全犯罪、恐怖活动犯罪、黑社会性质的组织犯罪的犯罪分子，刑罚执行完毕或者赦免以后，在任何时候再犯上述任一类罪的，都以累犯论处（无时间限制、无刑度要求）。累犯的法律后果：应当从重处罚；不适用缓刑；不得假释；不得单处罚金替代。" },
{ id: "XING-058", chapter: "拓展题库", type: "multi", difficulty: 3,
  stem: "关于缓刑，下列说法正确的有？",
  options: { A: "缓刑适用于被判处拘役、三年以下有期徒刑的犯罪分子", B: "对其中不满十八周岁的人、怀孕的妇女和已满七十五周岁的人，符合缓刑条件的应当宣告缓刑", C: "累犯和犯罪集团的首要分子不适用缓刑", D: "缓刑考验期满，原判刑罚视为已经执行完毕" },
  answer: ["A", "B", "C"],
  analysis: "A：应选。缓刑的对象条件是被判处拘役、三年以下有期徒刑。 B：应选。对这三类人符合条件的应当宣告缓刑（其他人是'可以'）。 C：应选。刑法第74条明确规定。 D：不应选。缓刑考验期满，原判的刑罚就不再执行，并公开予以宣告——是'不再执行'而非'视为执行完毕'（故缓刑期满后再犯罪不构成累犯）。 【考点】缓刑的适用条件：对象条件（拘役、三年以下有期徒刑）；实质条件（犯罪情节较轻；有悔罪表现；没有再犯罪的危险；宣告缓刑对所居住社区没有重大不良影响）；禁止条件（累犯和犯罪集团的首要分子不适用）。对不满18周岁、怀孕的妇女、已满75周岁的人，符合条件的应当宣告缓刑。考验期：拘役的为原判刑期以上1年以下，不得少于2个月；有期徒刑的为原判刑期以上5年以下，不得少于1年。缓刑的撤销：考验期内犯新罪或发现漏罪的，撤销缓刑数罪并罚；违反法律、行政法规或者监督管理规定情节严重的，撤销缓刑执行原判刑罚。考验期满原判刑罚不再执行，因未实际执行刑罚，此后再犯罪不构成累犯。" },
{ id: "XING-059", chapter: "拓展题库", type: "single", difficulty: 3,
  stem: "甲以非法占有为目的，虚构投资项目骗取乙100万元。甲的行为构成诈骗罪。诈骗罪的基本行为结构是？",
  options: { A: "欺骗行为→对方产生（或维持）错误认识→基于错误认识处分财产→行为人取得财产→被害人遭受财产损失", B: "欺骗行为→取得财产即可，无需对方处分行为", C: "只要有虚构事实的行为即构成诈骗既遂", D: "欺骗行为→对方恐惧→交付财物" },
  answer: ["A"],
  analysis: "A：正确。这是诈骗罪的完整构造，各环节须具备因果链条。 B：错误。处分行为（处分意识）是诈骗罪与盗窃罪（间接正犯形式）区分的关键。 C：错误。未取得财产或被害人未处分财产的，仅可能成立未遂。 D：错误。基于恐惧心理交付财物是敲诈勒索罪的结构。 【考点】诈骗罪的构造：行为人实施欺骗行为（虚构事实、隐瞒真相）→受骗者产生或者维持错误认识→受骗者基于错误认识处分（交付）财产→行为人或第三人取得财产→被害人遭受财产损失。处分行为及处分意识是诈骗与盗窃的分界：受骗人无处分意识而丧失财物的（如调包、机器不能被骗），成立盗窃罪。三角诈骗：受骗人与被害人不同一，但受骗人须有处分被害人财产的权限或地位（如诉讼诈骗中的法院）。诈骗数额较大（一般3千元以上）构成犯罪；与招摇撞骗罪、合同诈骗罪、集资诈骗罪等特殊诈骗罪按特别法条优先原则处理。" },
{ id: "XING-060", chapter: "拓展题库", type: "single", difficulty: 4,
  stem: "甲在商场将乙放在购物车内的手提包（内有现金2万元）趁乙转身挑选商品之际拿走。乙发现后追赶，甲将包扔还给乙后逃走。甲的行为构成？",
  options: { A: "盗窃罪既遂", B: "盗窃罪未遂", C: "盗窃罪中止", D: "侵占罪" },
  answer: ["A"],
  analysis: "A：正确。甲秘密窃取他人占有的财物，将包拿走时已建立新的占有支配（失控+控制），盗窃既遂；事后返还赃物不影响既遂的成立，仅是量刑情节。 B：错误。既遂标准通说采'失控+控制说'，甲取得对包的实际控制即既遂，返还不改变既遂形态。 C：错误。犯罪既遂后不存在中止；中止只能发生在犯罪过程中。 D：错误。购物车内的包仍由乙占有，甲打破他人占有，是盗窃而非侵占（侵占针对自己已合法占有的他人之物或脱离占有物）。 【考点】盗窃罪既遂的通说标准是控制说（失控+控制）：行为人取得对财物的实际控制、被害人丧失控制即为既遂。小件物品放入口袋、提包即可认定既遂，不要求带离现场。既遂后的返还、退赃只是量刑情节，不能变更犯罪形态为中止或未遂。盗窃与侵占的区分关键在于财物由谁占有：打破他人占有取得财物是盗窃；将自己业已合法占有（代为保管）的他人财物或者他人的遗忘物、埋藏物非法占为己有、拒不退还的是侵占。占有的判断包括事实支配与社会一般观念（如短暂遗忘于特定场所内的财物仍属被害人或场所管理人占有）。" },
{ id: "XING-061", chapter: "拓展题库", type: "multi", difficulty: 3,
  stem: "关于抢劫罪的加重情节（'八种加重'），下列属于法定加重处罚情形的有？",
  options: { A: "入户抢劫", B: "在公共交通工具上抢劫", C: "抢劫致人重伤、死亡", D: "抢劫数额较大" },
  answer: ["A", "B", "C"],
  analysis: "A：应选。'入户抢劫'是八种加重情节之一，'户'指供他人家庭生活的与外界相对隔离的住所。 B：应选。八种加重情节之一，包括正在运营中的公共汽车、火车、船只、飞机等。 C：应选。八种加重情节之一，含过失致人重伤死亡与故意伤害、杀害（抢劫过程中杀人的定抢劫罪一罪）。 D：不应选。加重情节是'抢劫数额巨大'，不是数额较大；抢劫罪的基本犯本无数额要求。 【考点】抢劫罪八种加重情节（十年以上有期徒刑、无期徒刑或者死刑）：入户抢劫；在公共交通工具上抢劫；抢劫银行或者其他金融机构；多次抢劫或者抢劫数额巨大；抢劫致人重伤、死亡；冒充军警人员抢劫；持枪抢劫；抢劫军用物资或者抢险、救灾、救济物资。要点辨析：'入户'须以侵害户内人员人身、财产为目的入户，入户后临时起意抢劫的也认定入户抢劫，但入户盗窃转化为抢劫的暴力须发生在户内；'持枪'指使用真枪（含未击发展示），假枪不算；'公共交通工具'不含小型出租车；为劫财而故意杀人的，以抢劫罪（致人死亡）一罪定罪处罚。" },
{ id: "XING-062", chapter: "拓展题库", type: "single", difficulty: 3,
  stem: "国家工作人员甲利用职务上的便利，将本单位公款50万元挪归个人使用进行营利活动，3个月后归还。甲的行为构成？",
  options: { A: "贪污罪", B: "挪用公款罪", C: "不构成犯罪，因已归还", D: "职务侵占罪" },
  answer: ["B"],
  analysis: "A：错误。贪污罪要求非法占有目的；甲挪用后归还，无占有目的。 B：正确。国家工作人员利用职务上的便利，挪用公款归个人使用，进行营利活动，数额较大的，构成挪用公款罪——营利型不要求超过3个月未还。 C：错误。挪用公款进行营利活动的，不以'超过三个月未还'为条件，归还只是量刑情节。 D：错误。职务侵占罪的主体是公司、企业或者其他单位的非国家工作人员；且甲无占有目的。 【考点】挪用公款罪的三种类型：挪用公款进行非法活动的（无数额和时间要求的从严掌握，数额较大起点更低）；挪用公款数额较大、进行营利活动的（不要求超过三个月未还）；挪用公款数额较大、超过三个月未还的（一般用途）。挪用公款归个人使用包括：供本人、亲友或者其他自然人使用；以个人名义将公款供其他单位使用；个人决定以单位名义将公款供其他单位使用、谋取个人利益的。与贪污罪的区别在于有无非法占有目的：携带挪用的公款潜逃的、挪用后采取虚假发票平账等手段使公款难以在账目上反映的、有能力归还而拒不归还的，以贪污罪定罪处罚。挪用公款数额巨大不退还的（客观不能退还），处十年以上有期徒刑或无期徒刑。" },
{ id: "XING-063", chapter: "拓展题库", type: "single", difficulty: 3,
  stem: "甲为使其子入学，送给某公办学校招生负责人乙5万元，乙利用职务便利违规录取。关于甲、乙的行为定性，下列说法正确的是？",
  options: { A: "乙构成受贿罪，甲构成行贿罪", B: "乙构成非国家工作人员受贿罪", C: "甲不构成犯罪，因系为子女教育", D: "甲乙构成受贿罪共犯" },
  answer: ["A"],
  analysis: "A：正确。公办学校中从事招生等公务的人员属于'其他依照法律从事公务的人员'，以国家工作人员论；乙利用职务便利收受财物为他人谋取利益构成受贿罪，甲为谋取不正当利益给予财物构成行贿罪。 B：错误。公办学校的招生录取属于公务活动，乙以国家工作人员论。 C：错误。为谋取不正当利益（违规录取）而给予国家工作人员财物，构成行贿罪，动机不影响定罪。 D：错误。行贿受贿是对合犯，分别定行贿罪与受贿罪，不作共犯处理。 【考点】受贿罪的主体是国家工作人员，包括：国家机关中从事公务的人员；国有公司、企业、事业单位、人民团体中从事公务的人员；受国家机关、国有单位委派到非国有单位从事公务的人员；其他依照法律从事公务的人员。公办学校、医院中从事管理性公务（招生、采购等）的人员以国家工作人员论。受贿罪的行为方式：利用职务上的便利，索取他人财物（索贿不要求为他人谋利，且从重处罚），或者非法收受他人财物为他人谋取利益。行贿罪要求'为谋取不正当利益'；因被勒索给予财物、没有获得不正当利益的，不是行贿。斡旋受贿：利用本人职权或地位形成的便利条件，通过其他国家工作人员职务上的行为为请托人谋取不正当利益的，以受贿论处。" },
{ id: "XING-064", chapter: "拓展题库", type: "multi", difficulty: 4,
  stem: "关于交通肇事罪及相关问题，下列说法正确的有？",
  options: { A: "交通肇事后逃逸致使被害人得不到救助而死亡的，处七年以上有期徒刑", B: "交通肇事后为逃避法律追究，将被害人带离现场隐藏、遗弃，致被害人死亡的，应以故意杀人罪定罪处罚", C: "单位主管人员、机动车辆所有人指使肇事人逃逸，致被害人因得不到救助而死亡的，以交通肇事罪的共犯论处", D: "醉酒驾驶机动车发生重大事故致人死亡的，一律以危险驾驶罪定罪" },
  answer: ["A", "B", "C"],
  analysis: "A：应选。'因逃逸致人死亡'是最重的加重情节，要求逃逸与死亡之间有因果关系。 B：应选。移置逃逸产生排他性支配的先行行为义务，放任死亡的成立不作为的故意杀人罪。 C：应选。司法解释明确规定的'过失犯罪共犯'特殊拟制。 D：不应选。醉驾致人重伤、死亡等构成交通肇事罪或以危险方法危害公共安全罪的，依照处罚较重的规定定罪处罚，危险驾驶罪仅是抽象危险犯的兜底。 【考点】交通肇事罪是过失犯罪，基本犯要求违反交通运输管理法规发生重大事故（致人重伤、死亡或者使公私财产遭受重大损失，如死亡1人或重伤3人以上负全部或主要责任）。三档法定刑：基本犯3年以下；交通运输肇事后逃逸或者有其他特别恶劣情节的，3-7年；因逃逸致人死亡的，7年以上。'因逃逸致人死亡'指为逃避法律追究而逃跑，致被害人得不到救助而死亡。移置逃逸（带离现场隐藏、遗弃）致死亡或严重残疾的，定故意杀人罪或故意伤害罪。危险驾驶罪（醉驾、追逐竞驶情节恶劣、严重超员超速、违规运输危化品）是故意的抽象危险犯，同时构成其他犯罪的从一重处断。" },
{ id: "XING-065", chapter: "拓展题库", type: "indeterminate", difficulty: 4,
  stem: "甲绑架乙后向乙父勒索赎金100万元。在控制乙期间，甲的下列行为应如何处理？",
  options: { A: "甲故意杀害乙的，以绑架罪一罪定罪，处无期徒刑或者死刑", B: "甲故意伤害乙致其重伤的，以绑架罪一罪从重定罪，处无期徒刑或者死刑", C: "甲收取赎金后释放乙，绑架罪既遂", D: "甲绑架过程中又强奸乙的，仅以绑架罪一罪处罚" },
  answer: ["A", "B", "C"],
  analysis: "A：应选。绑架中杀害被绑架人的，是绑架罪的加重情节（结合犯），不数罪并罚，处无期徒刑或者死刑，并处没收财产。 B：应选。杀害被绑架人，或者故意伤害被绑架人致人重伤、死亡的，同样适用该加重法定刑，以绑架罪一罪论。 C：应选。绑架罪的既遂以实际控制人质为标准（行为犯），是否取得赎金不影响既遂；取得赎金更属既遂无疑。 D：不应选。绑架中强奸被绑架人的，绑架罪与强奸罪数罪并罚（强奸不是绑架罪的加重情节）。 【考点】绑架罪是以勒索财物为目的绑架他人，或者绑架他人作为人质的行为，既遂标准是实际控制（劫持）人质，不以取得赎金为条件。加重处罚（无期徒刑或者死刑，并处没收财产）：杀害被绑架人的；故意伤害被绑架人，致人重伤、死亡的——这两类行为被绑架罪吸收，一罪处理。绑架中实施其他犯罪（强奸、抢劫人质随身财物等）的，数罪并罚（抢劫人质财物的定绑架罪与抢劫罪并罚是通行做法）。与非法拘禁罪（为索取债务扣押、拘禁他人的，定非法拘禁罪，包括索取高利贷等法律不予保护的债务）、敲诈勒索罪（未实际控制人质、以加害相威胁勒索财物）注意区分。" },
{ id: "XING-066", chapter: "拓展题库", type: "indeterminate", difficulty: 3,
  stem: "关于正当防卫与相关制度的比较，下列说法正确的是？",
  options: { A: "对不法侵害的防卫不要求侵害者具有刑事责任能力", B: "防卫不适时（事前防卫、事后防卫）不成立正当防卫", C: "假想防卫一律按过失犯罪处理", D: "相互斗殴中原则上不存在正当防卫，但一方停止斗殴或求饶后另一方继续侵害的，可以进行防卫" },
  answer: ["A", "B", "D"],
  analysis: "A：应选。不法侵害是客观违法概念，对无责任能力人（精神病人、未成年人）的侵害也可防卫，但应尽量优先躲避（限制防卫）。 B：应选。不法侵害尚未开始或者已经结束时进行的'防卫'，不符合时间条件，可能构成故意犯罪或过失犯罪。 C：不应选。假想防卫排除故意，有过失且法律有处罚过失规定的成立过失犯罪，无过失的属意外事件，并非一律过失犯罪。 D：应选。斗殴双方均有侵害故意，原则上无防卫可言；但斗殴结束后对方继续攻击，或者一方突然使用致命武器升级暴力的，另一方可成立正当防卫。 【考点】正当防卫的疑难点：不法侵害的'不法'是客观判断，对无责任能力人的攻击可以防卫；防卫的时间条件是不法侵害'正在进行'（着手至结束，财产犯罪虽既遂但现场还来得及挽回损失的视为仍在进行）。假想防卫：不存在不法侵害而误以为存在进行'防卫'，阻却故意，依有无过失分别成立过失犯罪或意外事件。防卫挑拨（故意挑逗对方侵害借机加害）不成立正当防卫。相互斗殴原则上无防卫，例外是斗殴升级或一方已退出。偶然防卫（无防卫意识但客观上制止了不法侵害）依行为无价值论成立犯罪（未遂），依结果无价值论无罪或未遂，考试注意学说立场。" },
{ id: "XING-067", chapter: "拓展题库", type: "multi", difficulty: 3,
  stem: "关于死刑的适用，下列说法正确的有？",
  options: { A: "死刑只适用于罪行极其严重的犯罪分子", B: "犯罪的时候不满十八周岁的人和审判的时候怀孕的妇女，不适用死刑", C: "审判的时候已满七十五周岁的人，一律不适用死刑", D: "判处死刑缓期执行的，在死刑缓期执行期间，如果没有故意犯罪，二年期满以后，减为无期徒刑" },
  answer: ["A", "B", "D"],
  analysis: "A：应选。刑法第48条确立的死刑适用总标准。 B：应选。绝对禁止，包括死缓。'审判的时候怀孕'包括羁押期间自然流产、人工流产的情形。 C：不应选。审判时已满75周岁的人不适用死刑，但以特别残忍手段致人死亡的除外。 D：应选。死缓期间没有故意犯罪的减为无期徒刑；确有重大立功表现的，二年期满以后减为二十五年有期徒刑；故意犯罪情节恶劣的，报请最高人民法院核准后执行死刑。 【考点】死刑适用的限制：实体限制（只适用于罪行极其严重的犯罪分子）；对象限制（犯罪时不满18周岁的人、审判时怀孕的妇女不适用死刑；审判时已满75周岁的人不适用死刑，但以特别残忍手段致人死亡的除外）；程序限制（死刑除依法由最高人民法院判决的以外，都应当报请最高人民法院核准）。死缓制度：应当判处死刑但不是必须立即执行的，可以判处死刑同时宣告缓期二年执行。死缓的结局：无故意犯罪→减为无期徒刑；确有重大立功→减为25年有期徒刑；故意犯罪情节恶劣→报最高法核准执行死刑（故意犯罪未执行死刑的，死缓期间重新计算）。对累犯及暴力性犯罪死缓犯，法院可以决定限制减刑。" },
{ id: "XING-068", chapter: "拓展题库", type: "single", difficulty: 2,
  stem: "甲捡到乙的信用卡后，持卡到ATM机取款2万元。甲的行为构成？",
  options: { A: "信用卡诈骗罪", B: "盗窃罪", C: "侵占罪", D: "不构成犯罪" },
  answer: ["A"],
  analysis: "A：正确。拾得他人信用卡并使用的，属于'冒用他人信用卡'，构成信用卡诈骗罪——司法解释明确包括在ATM机上使用的情形。 B：错误。盗窃信用卡并使用的才依盗窃罪定罪；拾得后使用定信用卡诈骗罪。 C：错误。侵占针对的是卡片本身价值微小，冒用取款行为被评价为信用卡诈骗。 D：错误。冒用他人信用卡数额较大（5千元以上）即构成信用卡诈骗罪。 【考点】信用卡诈骗罪的行为类型：使用伪造的信用卡或者以虚假身份证明骗领的信用卡；使用作废的信用卡；冒用他人信用卡（包括拾得他人信用卡并使用、骗取他人信用卡并使用、窃取/收买/骗取他人信用卡信息资料并通过互联网、通讯终端使用等）；恶意透支（持卡人以非法占有为目的，超过规定限额或者规定期限透支，经发卡银行两次有效催收后超过三个月仍不归还）。特别规定：盗窃信用卡并使用的，依照盗窃罪定罪处罚（法律拟制）。拾得信用卡在ATM机上取款，最高检批复认定为冒用他人信用卡，构成信用卡诈骗罪。" },
{ id: "XING-069", chapter: "拓展题库", type: "single", difficulty: 3,
  stem: "甲在网上散布虚假的地震预警信息，在信息网络上大量传播，严重扰乱社会秩序。甲的行为构成？",
  options: { A: "编造、故意传播虚假信息罪", B: "寻衅滋事罪", C: "诽谤罪", D: "不构成犯罪" },
  answer: ["A"],
  analysis: "A：正确。编造虚假的险情、疫情、灾情、警情，在信息网络或者其他媒体上传播，严重扰乱社会秩序的，构成编造、故意传播虚假信息罪。 B：错误。编造传播虚假的'四情'信息有专门罪名，特别法条优先；网络寻衅滋事针对的是其他虚假信息起哄闹事情形。 C：错误。诽谤针对特定自然人的名誉，本题针对公共秩序。 D：错误。严重扰乱社会秩序即达到入罪标准。 【考点】编造、故意传播虚假信息罪（刑法第291条之一第2款）：编造虚假的险情、疫情、灾情、警情，在信息网络或者其他媒体上传播，或者明知是上述虚假信息故意在信息网络或者其他媒体上传播，严重扰乱社会秩序的，处三年以下有期徒刑、拘役或者管制；造成严重后果的，处三年以上七年以下有期徒刑。注意与编造、故意传播虚假恐怖信息罪（爆炸威胁、生化威胁、放射威胁等恐怖信息）的区分。利用信息网络辱骂、恐吓他人或编造虚假信息起哄闹事，破坏社会秩序的，可构成寻衅滋事罪。区分的关键是信息类型：'四情'信息适用本罪。" },
{ id: "XING-070", chapter: "拓展题库", type: "single", difficulty: 3,
  stem: "甲公司为骗取银行贷款，提供虚假财务报表获得贷款500万元，到期无法偿还，给银行造成重大损失，但无证据证明甲公司有非法占有目的。甲公司及直接责任人员构成？",
  options: { A: "贷款诈骗罪", B: "骗取贷款罪", C: "合同诈骗罪", D: "不构成犯罪" },
  answer: ["B"],
  analysis: "A：错误。贷款诈骗罪要求以非法占有为目的，且单位不能构成贷款诈骗罪。 B：正确。以欺骗手段取得银行贷款，给银行造成重大损失，但无非法占有目的的，构成骗取贷款、票据承兑、金融票证罪，单位可以构成本罪。 C：错误。合同诈骗罪同样以非法占有为目的为要件。 D：错误。欺骗取得贷款并造成重大损失已构成骗取贷款罪。 【考点】骗取贷款罪与贷款诈骗罪的区分核心是有无非法占有目的：有非法占有目的（携款潜逃、肆意挥霍、用于违法犯罪活动、抽逃转移资金等）构成贷款诈骗罪（仅自然人可构成）；无非法占有目的、仅以欺骗手段获取贷款，给银行或者其他金融机构造成重大损失的，构成骗取贷款罪（自然人与单位均可构成）。刑法修正案（十一）将骗取贷款罪的入罪门槛调整为'造成重大损失'，删去'或者有其他严重情节'作为基本犯标准（其他特别严重情节保留在加重档）。单位犯罪实行双罚制：对单位判处罚金，并对直接负责的主管人员和其他直接责任人员判处刑罚。" },
{ id: "XING-071", chapter: "拓展题库", type: "single", difficulty: 2,
  stem: "甲明知乙实施电信网络诈骗，仍将自己的银行卡提供给乙用于转移诈骗资金，获利5000元。甲的行为构成？",
  options: { A: "帮助信息网络犯罪活动罪", B: "诈骗罪的共犯（若仅有概括明知而无通谋）", C: "非法经营罪", D: "不构成犯罪" },
  answer: ["A"],
  analysis: "A：正确。明知他人利用信息网络实施犯罪，为其犯罪提供支付结算等帮助，情节严重的，构成帮助信息网络犯罪活动罪（'帮信罪'）。 B：错误。无事前通谋、仅概括性明知他人利用网络犯罪而提供帮助的，以帮信罪论处；有通谋的才按诈骗共犯处理。 C：错误。提供银行卡帮助结算不属于非法经营罪的调整范围。 D：错误。明知+提供支付结算帮助+情节严重，构成帮信罪。 【考点】帮助信息网络犯罪活动罪（刑法第287条之二）：明知他人利用信息网络实施犯罪，为其犯罪提供互联网接入、服务器托管、网络存储、通讯传输等技术支持，或者提供广告推广、支付结算等帮助，情节严重的，处三年以下有期徒刑或者拘役，并处或者单处罚金。'明知'可以综合交易价格异常、频繁更换通讯工具、事先约定逃避监管等情形推定。与上游犯罪共犯的界分：事前通谋的，以共同犯罪论处；同时构成其他犯罪的，依照处罚较重的规定定罪处罚。出售、出租银行卡、电话卡供犯罪使用（'两卡'犯罪）是当前打击重点，还可能构成掩饰、隐瞒犯罪所得罪或妨害信用卡管理罪。" },
{ id: "XING-072", chapter: "拓展题库", type: "single", difficulty: 4,
  stem: "甲以出卖为目的，偷盗婴儿并卖给他人，获款8万元。甲的行为构成？",
  options: { A: "拐卖儿童罪，且属于'偷盗婴幼儿'的加重情节", B: "拐骗儿童罪", C: "盗窃罪", D: "拐卖儿童罪与遗弃罪并罚" },
  answer: ["A"],
  analysis: "A：正确。以出卖为目的偷盗婴幼儿的，是拐卖儿童罪的加重情节，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产。 B：错误。拐骗儿童罪无出卖目的（脱离家庭或监护人）；甲以出卖为目的，构成拐卖儿童罪。 C：错误。婴儿是人不是财物，不能成为盗窃罪对象。 D：错误。出卖行为是拐卖儿童罪的实行内容，不另构成遗弃罪。 【考点】拐卖妇女、儿童罪是指以出卖为目的，拐骗、绑架、收买、贩卖、接送、中转妇女、儿童的行为之一。八种加重情节（十年以上或无期）包括：拐卖集团首要分子；拐卖三人以上；奸淫被拐卖的妇女；诱骗、强迫被拐卖的妇女卖淫或者卖给他人迫使卖淫；以出卖为目的使用暴力、胁迫或者麻醉方法绑架妇女、儿童；以出卖为目的偷盗婴幼儿；造成被拐卖的人或者其亲属重伤、死亡或者其他严重后果；将妇女、儿童卖往境外。情节特别严重的处死刑。区分罪名：无出卖目的偷盗婴幼儿、拐骗不满14周岁未成年人脱离家庭或监护人的是拐骗儿童罪；收买被拐卖的妇女、儿童的构成收买被拐卖的妇女、儿童罪。" },
{ id: "XING-073", chapter: "拓展题库", type: "multi", difficulty: 3,
  stem: "关于强奸罪，下列说法正确的有？",
  options: { A: "与不满十四周岁的幼女发生性关系，不论幼女是否同意，均以强奸论，从重处罚", B: "强奸妇女、奸淫幼女情节恶劣的，属于加重处罚情形", C: "丈夫在任何情况下都不能成为强奸妻子的主体", D: "利用妇女熟睡、醉酒等不知反抗状态与之发生性关系的，构成强奸罪" },
  answer: ["A", "B", "D"],
  analysis: "A：应选。奸淫不满十四周岁的幼女的，以强奸论，从重处罚（对不满12周岁的，行为人应当知道其是幼女）。 B：应选。强奸罪加重情节包括：情节恶劣、强奸多人、在公共场所当众强奸、二人以上轮奸、奸淫不满十周岁的幼女或者造成幼女伤害、致使被害人重伤死亡或造成其他严重后果。 C：不应选。婚姻关系非正常存续期间（如离婚诉讼期间分居）以暴力手段强行发生性关系的，实务中可以强奸罪论处。 D：应选。违背妇女意志是本质，利用不知反抗、不能反抗状态同样构成。 【考点】强奸罪的本质是违背妇女意志，以暴力、胁迫或者其他手段（灌醉、麻醉、利用熟睡患病、冒充丈夫、利用迷信等使被害人不知反抗、不能反抗、不敢反抗）强行发生性关系。奸淫幼女的特殊规则：不满14周岁的幼女无性同意能力，'同意'无效，一律以强奸论并从重处罚；对不满12周岁的被害人，推定行为人明知是幼女；已满14不满16周岁的男少年与幼女自愿发生性行为，情节轻微、未造成严重后果的，不认为是犯罪。刑法修正案（十一）增设负有照护职责人员性侵罪：对已满14不满16周岁的未成年女性负有监护、收养、看护、教育、医疗等特殊职责的人员与其发生性关系的，即使'自愿'也构成犯罪。" },
{ id: "XING-074", chapter: "拓展题库", type: "single", difficulty: 3,
  stem: "甲在拆迁纠纷中，将汽油泼洒在自己身上，在人员密集的政府办公楼大厅内点燃，引起大火烧毁大厅设施并致两名工作人员轻伤。甲的行为构成？",
  options: { A: "放火罪", B: "故意毁坏财物罪", C: "自杀行为不构成犯罪", D: "寻衅滋事罪" },
  answer: ["A"],
  analysis: "A：正确。在人员密集场所点燃汽油，足以危害公共安全（不特定或多数人的生命、健康、重大财产安全），构成放火罪。 B：错误。行为危及公共安全，超出了单纯毁财的范围。 C：错误。自焚方式危害公共安全的，仍构成放火罪，自杀动机不阻却犯罪。 D：错误。危害公共安全的放火行为应定放火罪，罪质更重。 【考点】放火罪是危害公共安全罪，保护法益是不特定或者多数人的生命、健康和重大公私财产安全。既遂标准采'独立燃烧说'：目的物开始独立燃烧（脱离引火媒介能继续燃烧）即为既遂，不要求造成实际严重后果。刑法第114条（尚未造成严重后果，3-10年）与第115条（致人重伤、死亡或者使公私财产遭受重大损失，10年以上、无期或死刑）是危险犯与实害犯的关系。烧毁自己财物但危及公共安全的，同样构成放火罪。与故意毁坏财物罪的区分：是否危害公共安全——在空旷无人处烧毁特定财物不危及公共安全的，定故意毁坏财物罪。" },
{ id: "XING-075", chapter: "拓展题库", type: "single", difficulty: 2,
  stem: "甲非法买卖枪支被抓获。关于非法买卖枪支的犯罪主观方面，下列说法正确的是？",
  options: { A: "本罪只能由故意构成", B: "过失买卖枪支也构成本罪", C: "须以营利为目的", D: "须造成严重后果才构成犯罪" },
  answer: ["A"],
  analysis: "A：正确。非法买卖枪支罪是故意犯罪，要求明知是枪支而非法买卖。 B：错误。本罪无过失形态；过失犯罪法律有规定的才负刑事责任。 C：错误。本罪不要求营利目的，非法买卖行为本身即具刑事可罚性。 D：错误。本罪是行为犯/抽象危险犯，实施非法买卖枪支行为即可构成。 【考点】非法制造、买卖、运输、邮寄、储存枪支、弹药、爆炸物罪是行为犯，只要实施相应行为即构成犯罪，不要求实际危害后果，也不要求营利目的。犯罪故意的一般原理：明知自己的行为会发生危害社会的结果，并且希望（直接故意）或者放任（间接故意）这种结果发生。过失犯罪：应当预见自己的行为可能发生危害社会的结果，因为疏忽大意而没有预见（疏忽大意的过失），或者已经预见而轻信能够避免（过于自信的过失），以致发生这种结果的。过失犯罪，法律有规定的才负刑事责任；刑法以处罚故意为原则、处罚过失为例外。" },
{ id: "XING-076", chapter: "拓展题库", type: "single", difficulty: 4,
  stem: "甲雇凶手乙杀丙，乙接受雇佣后仅将丙打成重伤即放弃（自动停止且丙未死）。关于甲、乙的犯罪形态，下列说法正确的是？",
  options: { A: "乙成立故意杀人罪中止，甲成立故意杀人罪未遂", B: "甲、乙均成立犯罪中止", C: "甲、乙均成立犯罪未遂", D: "乙成立故意伤害罪既遂" },
  answer: ["A"],
  analysis: "A：正确。中止具有一身专属性：乙自动放弃犯罪成立中止（造成损害应减轻处罚）；甲无中止行为，因乙的中止（甲意志以外的原因）致犯罪未得逞，甲成立未遂。 B：错误。中止的自动性是个人事由，不及于未自动放弃的共犯人。 C：错误。乙系自动放弃，符合中止要件。 D：错误。乙基于杀人故意实施行为后中止，应认定故意杀人罪（中止），造成重伤的减轻处罚，而非改定伤害罪。 【考点】共同犯罪中的犯罪中止具有个别性（一身专属性）：只有自动放弃犯罪或自动有效防止犯罪结果发生的共犯人才成立中止；其他共犯人因意志以外的原因未得逞的，成立未遂。共犯关系的脱离：帮助犯、教唆犯欲成立中止，必须消除自己先前行为对犯罪的促进作用（如撤回帮助、说服实行犯放弃）；仅自己消极不参与而犯罪结果仍发生的，不成立中止。雇凶杀人中雇主是教唆犯（或组织支配的共谋共同正犯），对实行者所处形态在其故意范围内负责。中止犯的处罚：没有造成损害的应当免除处罚，造成损害的应当减轻处罚。" },
{ id: "XING-077", chapter: "拓展题库", type: "single", difficulty: 3,
  stem: "甲伪造货币30万元后，又将伪造的货币运输至外地出售。对甲应如何处理？",
  options: { A: "以伪造货币罪定罪从重处罚", B: "伪造货币罪与出售、运输假币罪数罪并罚", C: "仅定出售、运输假币罪", D: "择一重罪处罚" },
  answer: ["A"],
  analysis: "A：正确。伪造货币并出售或者运输伪造的货币的，依照伪造货币罪定罪从重处罚（吸收关系，不并罚）。 B：错误。刑法第171条第3款明确规定以伪造货币罪定罪从重处罚。 C：错误。伪造行为是源头行为，罪质更重，应定伪造货币罪。 D：错误。这不是想象竞合的择一重，而是法律明文规定的定罪从重规则。 【考点】货币犯罪的罪数规则：伪造货币并出售或者运输伪造的货币的，依照伪造货币罪定罪从重处罚（第171条第3款）——伪造行为吸收后续的出售、运输行为。出售、购买伪造的货币或者明知是伪造的货币而运输，数额较大的，构成出售、购买、运输假币罪。银行或者其他金融机构的工作人员购买伪造的货币或者利用职务上的便利，以伪造的货币换取货币的，从重处罚（金融工作人员购买假币、以假币换取货币罪）。明知是伪造的货币而持有、使用，数额较大的，构成持有、使用假币罪。伪造货币罪的对象包括正在流通的人民币和境外货币。" },
{ id: "XING-078", chapter: "拓展题库", type: "multi", difficulty: 3,
  stem: "关于洗钱罪（刑法第191条），下列说法正确的有？",
  options: { A: "上游犯罪包括毒品犯罪、黑社会性质的组织犯罪、恐怖活动犯罪、走私犯罪、贪污贿赂犯罪、破坏金融管理秩序犯罪、金融诈骗犯罪七类", B: "刑法修正案（十一）后，'自洗钱'行为可以构成洗钱罪", C: "掩饰、隐瞒七类之外犯罪所得的，可能构成掩饰、隐瞒犯罪所得、犯罪所得收益罪", D: "洗钱罪的成立以上游犯罪的行为人已被定罪判刑为前提" },
  answer: ["A", "B", "C"],
  analysis: "A：应选。洗钱罪的上游犯罪限于这七类犯罪。 B：应选。修正案删除了'明知''协助'等表述，上游犯罪本犯掩饰、隐瞒自己犯罪所得及其收益的（自洗钱），也构成洗钱罪，与上游犯罪数罪并罚。 C：应选。七类上游犯罪之外的赃物犯罪适用第312条掩饰、隐瞒犯罪所得罪。 D：不应选。上游犯罪事实上成立即可，上游犯罪人尚未依法裁判或因死亡等原因未被追究刑事责任，不影响洗钱罪的认定。 【考点】洗钱罪是为掩饰、隐瞒七类上游犯罪（毒品犯罪、黑社会性质的组织犯罪、恐怖活动犯罪、走私犯罪、贪污贿赂犯罪、破坏金融管理秩序犯罪、金融诈骗犯罪）的所得及其产生的收益的来源和性质，实施提供资金账户、转换财产形式、转移资金、跨境转移资产等行为。刑法修正案（十一）的重大变化：自洗钱入罪——上游犯罪本犯对自己的犯罪所得进行洗钱的，构成洗钱罪并与上游犯罪并罚；删除'明知'表述但主观上仍须认识到系犯罪所得。上游犯罪查证属实即可，不以生效裁判为前提。与掩饰、隐瞒犯罪所得罪是特别法与一般法的关系。" },
{ id: "XING-079", chapter: "拓展题库", type: "single", difficulty: 3,
  stem: "甲组织多名残疾人在街头乞讨并从中牟利，对不服从者以殴打相威胁。甲的行为构成？",
  options: { A: "组织残疾人、儿童乞讨罪", B: "强迫劳动罪", C: "寻衅滋事罪", D: "不构成犯罪" },
  answer: ["A"],
  analysis: "A：正确。以暴力、胁迫手段组织残疾人或者不满十四周岁的未成年人乞讨的，构成组织残疾人、儿童乞讨罪。 B：错误。乞讨不属于劳动，有专门罪名规制。 C：错误。甲的行为符合专门罪名的构成要件。 D：错误。以暴力、胁迫手段组织残疾人乞讨即构成本罪。 【考点】组织残疾人、儿童乞讨罪（刑法第262条之一）：以暴力、胁迫手段组织残疾人或者不满十四周岁的未成年人乞讨的，处三年以下有期徒刑或者拘役，并处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金。构成要件要点：手段限于暴力、胁迫（平和手段组织乞讨不构成本罪）；对象限于残疾人或不满14周岁的未成年人。相关罪名：组织未成年人进行违反治安管理活动罪（组织未成年人盗窃、诈骗、抢夺、敲诈勒索等）；雇用童工从事危重劳动罪；强迫劳动罪（以暴力、威胁或者限制人身自由的方法强迫他人劳动）。" },
{ id: "XING-080", chapter: "拓展题库", type: "single", difficulty: 2,
  stem: "关于单位犯罪，下列说法正确的是？",
  options: { A: "公司、企业、事业单位、机关、团体实施的危害社会的行为，法律规定为单位犯罪的，应当负刑事责任", B: "一切犯罪单位均可构成", C: "单位犯罪只处罚单位，不处罚个人", D: "个人为进行违法犯罪活动而设立的公司实施犯罪的，以单位犯罪论处" },
  answer: ["A"],
  analysis: "A：正确。单位犯罪以法律明文规定为限（法定性），刑法分则没有规定单位可以构成的犯罪，单位实施的只能追究相关自然人的责任。 B：错误。单位犯罪以刑法分则明文规定为限，如贷款诈骗罪、盗窃罪等单位不能构成。 C：错误。原则上实行双罚制：对单位判处罚金，并对直接负责的主管人员和其他直接责任人员判处刑罚。 D：错误。个人为进行违法犯罪活动而设立的公司、企业、事业单位实施犯罪的，或者设立后以实施犯罪为主要活动的，不以单位犯罪论处，按自然人犯罪处理。 【考点】单位犯罪的成立条件：主体是公司、企业、事业单位、机关、团体；以单位名义实施；为单位谋取非法利益（违法所得归单位）；法律明文规定单位可以构成该罪。处罚原则是双罚制（对单位判处罚金，对直接负责的主管人员和其他直接责任人员判处刑罚），刑法分则另有规定的实行单罚制（只处罚责任人员）。不以单位犯罪论处的情形：个人为进行违法犯罪活动而设立的单位实施犯罪；单位设立后以实施犯罪为主要活动的；盗用单位名义实施犯罪、违法所得由个人私分的。单位被撤销、注销、吊销营业执照或者宣告破产的，追究直接责任人员的刑事责任。" },
{ id: "XING-081", chapter: "拓展题库", type: "multi", difficulty: 4,
  stem: "关于贪污罪与职务侵占罪、挪用公款罪与挪用资金罪的区分，下列说法正确的有？",
  options: { A: "贪污罪与职务侵占罪的主要区别在于主体：前者是国家工作人员，后者是公司、企业或者其他单位中的非国家工作人员", B: "国有公司中从事公务的人员利用职务便利非法占有本单位财物的，构成贪污罪", C: "受国有单位委派到非国有公司从事公务的人员，非法占有该非国有公司财物的，构成职务侵占罪", D: "村民委员会等基层组织人员协助人民政府从事行政管理工作（如管理救灾款物）时，利用职务便利非法占有公共财物的，以贪污罪论处" },
  answer: ["A", "B", "D"],
  analysis: "A：应选。两罪行为方式类似（利用职务便利侵吞、窃取、骗取本单位财物），区别在主体身份及对象（公共财物/本单位财物）。 B：应选。国有公司、企业中从事公务的人员属于国家工作人员，构成贪污罪。 C：不应选。受委派从事公务的人员以国家工作人员论，构成贪污罪。 D：应选。依立法解释，村基层组织人员协助政府从事救灾、抢险、防汛、优抚、扶贫款物管理等行政管理工作时，属于'其他依照法律从事公务的人员'，可构成贪污罪、受贿罪、挪用公款罪。 【考点】身份决定罪名是职务犯罪的核心逻辑。国家工作人员（国家机关从事公务人员、国有单位从事公务人员、受委派从事公务人员、其他依法从事公务人员）利用职务便利：非法占有公共财物→贪污罪；挪用公款归个人使用→挪用公款罪；收受财物为人谋利→受贿罪。非国家工作人员（公司、企业或其他单位人员）对应：职务侵占罪、挪用资金罪、非国家工作人员受贿罪。村民委员会等基层组织人员的双重身份：协助人民政府从事七类行政管理工作时以国家工作人员论；管理村集体自治事务（如集体经营收益分配）时按非国家工作人员对待。委派的关键是代表国有单位在非国有单位中从事组织、领导、监督、管理等公务。" },
{ id: "XING-082", chapter: "拓展题库", type: "single", difficulty: 3,
  stem: "甲长期虐待其10岁的儿子乙，经常打骂、冻饿，致乙轻微伤多处。情节恶劣。甲的行为构成？",
  options: { A: "虐待罪", B: "故意伤害罪", C: "遗弃罪", D: "不构成犯罪，属家庭内部事务" },
  answer: ["A"],
  analysis: "A：正确。虐待家庭成员，情节恶劣的，构成虐待罪。经常性打骂、冻饿等肉体和精神摧残即为虐待。 B：错误。故意伤害要求达到轻伤以上；持续性、经常性的家庭摧残行为宜评价为虐待罪。 C：错误。遗弃是对需要扶养者拒绝扶养（不作为），虐待是积极的摧残行为。 D：错误。虐待家庭成员情节恶劣即构成犯罪；对未成年人的保护更不容'家务事'抗辩。 【考点】虐待罪：虐待家庭成员，情节恶劣的，处二年以下有期徒刑、拘役或者管制；致使被害人重伤、死亡的（指虐待行为导致的结果加重，如长期虐待致衰竭死亡或被害人不堪虐待自杀），处二年以上七年以下有期徒刑。告诉才处理，但被害人没有能力告诉，或者因受到强制、威吓无法告诉的除外（对被虐待的未成年人、老年人等，公安司法机关可依职权追究）。虐待过程中故意造成轻伤、重伤结果的，另构成故意伤害罪，从一重或并罚视具体情形。相关罪名：虐待被监护、看护人罪（对未成年人、老年人、患病的人、残疾人等负有监护、看护职责的人虐待被监护、看护的人，情节恶劣的——非家庭成员关系，公诉案件）。" },
{ id: "XING-083", chapter: "拓展题库", type: "single", difficulty: 3,
  stem: "甲敲诈勒索乙，声称不给10万元就举报乙的犯罪事实。乙确实实施过犯罪。甲的行为如何定性？",
  options: { A: "构成敲诈勒索罪", B: "不构成犯罪，因举报内容真实", C: "构成诈骗罪", D: "构成抢劫罪" },
  answer: ["A"],
  analysis: "A：正确。以举报相要挟索取财物，即使所举报内容真实，仍属以恶害相通告使人恐惧而交付财物，构成敲诈勒索罪。行使举报权不能成为勒索财物的手段。 B：错误。举报自由不包含借此索财的自由，手段与目的的结合具有违法性。 C：错误。乙非基于错误认识而是基于恐惧心理交付财物，是敲诈勒索而非诈骗。 D：错误。抢劫要求暴力、胁迫达到压制反抗程度且具有当场性；本题是敲诈勒索的恐吓。 【考点】敲诈勒索罪的结构：以恶害相通告（威胁、要挟）→对方产生恐惧心理→基于恐惧交付财物→行为人取得财物。威胁内容可以是暴力、毁坏名誉、揭发隐私或犯罪事实等，威胁内容本身是否合法、所揭发事实是否真实，不影响本罪成立——关键是行为人无权以此索取财物。与抢劫罪的区分（两个当场）：抢劫是当场以暴力侵害相威胁、当场取得财物，暴力程度足以压制反抗；敲诈勒索的威胁通常不具有当场即时实现暴力的特征，被害人尚有意志自由。与诈骗罪区分：被害人交付财物的心理基础是恐惧还是错误认识。行使正当权利（如索赔）与敲诈勒索的界限看权利基础与手段的相当性。" },
{ id: "XING-084", chapter: "拓展题库", type: "single", difficulty: 2,
  stem: "甲将其邻居乙（女）非法关押在地下室3天，以迫使乙偿还欠款。甲的行为构成？",
  options: { A: "非法拘禁罪", B: "绑架罪", C: "抢劫罪", D: "敲诈勒索罪" },
  answer: ["A"],
  analysis: "A：正确。为索取债务非法扣押、拘禁他人的，构成非法拘禁罪（而非绑架罪）。 B：错误。为索取（真实存在的）债务扣押他人的定非法拘禁罪；绑架罪是勒索型或人质型犯罪。 C：错误。索债目的与非法占有他人财物的抢劫目的不同。 D：错误。甲控制了乙的人身自由，且索取的是债务，符合非法拘禁罪的特征。 【考点】非法拘禁罪是非法剥夺他人人身自由的行为，为索取债务（包括高利贷、赌债等法律不予保护的债务）非法扣押、拘禁他人的，依照非法拘禁罪定罪处罚——这是与绑架罪区分的法定规则。非法拘禁具有殴打、侮辱情节的，从重处罚。结果加重与转化：非法拘禁致人重伤的处三年以上十年以下；致人死亡的处十年以上；使用暴力致人伤残、死亡的（超出拘禁行为本身的暴力），依照故意伤害罪、故意杀人罪定罪处罚（转化犯）。国家机关工作人员利用职权犯非法拘禁罪的，从重处罚。绑架罪的勒索对象是无债务关系的'赎金'，若索取数额明显超过债务的，超出部分可能认定绑架或敲诈勒索。" },
{ id: "XING-085", chapter: "拓展题库", type: "multi", difficulty: 3,
  stem: "关于毒品犯罪，下列说法正确的有？",
  options: { A: "走私、贩卖、运输、制造毒品，无论数量多少，都应当追究刑事责任", B: "贩卖毒品罪的既遂不以毒品实际交付为必要，进入交易环节即可认定", C: "吸毒者购买、存储数量较大毒品仅供自吸的，构成非法持有毒品罪", D: "容留他人吸食毒品并向其出售毒品的，仅定容留他人吸毒罪" },
  answer: ["A", "B", "C"],
  analysis: "A：应选。刑法第347条明确规定，本罪无数量门槛。 B：应选。实务采'进入交易说'，为贩卖而购买毒品或者带毒品赴约交易的，均可认定既遂（存在争议但系主流实务立场）。 C：应选。无贩卖等目的、持有毒品数量较大的，构成非法持有毒品罪。 D：不应选。容留吸毒又贩卖毒品的，数罪并罚（贩卖毒品罪与容留他人吸毒罪）。 【考点】毒品犯罪体系：走私、贩卖、运输、制造毒品罪是选择性罪名，无论数量多少均追究刑事责任，数量影响量刑（鸦片1千克、海洛因或甲基苯丙胺50克以上处15年、无期或死刑）。毒品数量以查证属实的走私、贩卖、运输、制造、非法持有毒品的数量计算，不以纯度折算。非法持有毒品罪是兜底罪名（无法证明走私、贩卖等目的时适用）。利用、教唆未成年人走私、贩卖、运输、制造毒品，或者向未成年人出售毒品的，从重处罚。毒品再犯：因走私、贩卖、运输、制造、非法持有毒品罪被判过刑，又犯本节规定之罪的，从重处罚（与累犯可并存适用）。" },
{ id: "XING-086", chapter: "拓展题库", type: "single", difficulty: 4,
  stem: "甲以危险方法危害公共安全案件中，'与放火、决水、爆炸、投放危险物质相当的其他危险方法'的认定，下列理解正确的是？",
  options: { A: "该罪是兜底罪名，任何危害公共安全的行为均可认定", B: "'其他危险方法'必须具有与放火、爆炸等相当的导致不特定或者多数人重伤、死亡的高度危险性", C: "在城市道路上普通超速驾驶即可构成本罪", D: "本罪属于过失犯罪" },
  answer: ["B"],
  analysis: "A：错误。'其他危险方法'须与放火、决水、爆炸、投放危险物质的危险性相当，不能无限扩张（防止口袋化）。 B：正确。同类解释规则：兜底条款的解释须与所列举行为保持性质与程度的相当性，即一次性造成多数人伤亡的具体公共危险。 C：错误。普通交通违章缺乏相当危险性；仅在如高速逆行冲撞人群等极端情形才可能构成。 D：错误。以危险方法危害公共安全罪是故意犯罪；过失形态是过失以危险方法危害公共安全罪。 【考点】以危险方法危害公共安全罪（第114条、115条）中'其他危险方法'的限定解释是重要考点：依据同类解释规则，必须与放火、决水、爆炸、投放危险物质在危险性质和程度上相当，即行为具有一次性导致不特定或者多数人重伤、死亡的内在高度危险。实务认定的典型：驾车冲撞人群、在公共场所私拉电网、盗窃道路井盖（危及公共交通安全的）、向人群密集场所开枪扫射等。防止'口袋罪'倾向：醉驾、一般高空抛物、破坏偷盗普通设施等应优先适用危险驾驶罪、高空抛物罪、破坏交通设施罪等specific罪名。高空抛物罪（刑法修正案十一新增）：从建筑物或者其他高空抛掷物品，情节严重的，处一年以下有期徒刑、拘役或者管制；同时构成其他犯罪的，从一重处罚。" },
{ id: "XING-087", chapter: "拓展题库", type: "indeterminate", difficulty: 4,
  stem: "甲深夜盗窃乙家，窃得现金3万元。逃离时被乙发现追赶，甲逃至街上将现金扔掉后仍被群众抓获扭送公安机关。到案后甲主动交代了三个月前另一次入户盗窃5万元的事实（公安机关尚未掌握）。下列说法正确的是？",
  options: { A: "甲本次盗窃构成既遂", B: "甲扔掉现金的行为构成犯罪中止", C: "甲交代未被掌握的前次盗窃，就该次盗窃以自首论", D: "两次盗窃数额应累计计算" },
  answer: ["A", "D"],
  analysis: "A：应选。甲窃得现金离开乙家即取得控制，既遂成立；逃跑中抛弃赃物不影响既遂。 B：不应选。既遂后无中止可言；抛赃是逃避抓捕的处分行为。 C：不应选。准自首要求供述的是司法机关还未掌握的本人'其他罪行'，依司法解释指不同种罪行；甲供述的是同种罪行（盗窃），不以自首论，但可以酌情从轻处罚，供述的同种罪行较重的一般应当从轻处罚。 D：应选。多次盗窃未经处理的，盗窃数额累计计算。 【考点】本题综合考查盗窃既遂标准、准自首与数额累计。既遂采控制说，取得控制即既遂，事后抛赃、退赃不改变形态。准自首（余罪自首）：被采取强制措施的犯罪嫌疑人、被告人和正在服刑的罪犯，如实供述司法机关还未掌握的本人'其他罪行'的，以自首论；依司法解释，'其他罪行'指与司法机关已掌握的罪行属不同种罪行——供述同种罪行的不认定自首，但可以酌情从轻处罚，如实供述同种罪行较重的一般应当从轻。多次盗窃、贪污、受贿等未经处理的，数额累计计算。二年内盗窃三次以上的构成'多次盗窃'，不受数额较大限制。" },
{ id: "XING-088", chapter: "拓展题库", type: "indeterminate", difficulty: 3,
  stem: "关于罚金和没收财产，下列说法正确的是？",
  options: { A: "罚金在判决指定的期限内一次或者分期缴纳；期满不缴纳的，强制缴纳", B: "由于遭遇不能抗拒的灾祸等原因缴纳确实有困难的，经法院裁定，可以延期缴纳、酌情减少或者免除", C: "没收财产是没收犯罪分子个人所有财产的一部或者全部；不得没收属于其家属所有或者应有的财产", D: "没收财产以前犯罪分子所负的正当债务，无论如何不得以没收的财产偿还" },
  answer: ["A", "B", "C"],
  analysis: "A：应选。刑法第53条规定；对于不能全部缴纳的，法院在任何时候发现被执行人有可以执行的财产，应当随时追缴。 B：应选。这是罚金的减免制度。 C：应选。没收财产的范围限于犯罪分子个人所有财产，家属所有或应有的财产不得没收。 D：不应选。没收财产以前犯罪分子所负的正当债务，需要以没收的财产偿还的，经债权人请求，应当偿还。 【考点】罚金与没收财产同属财产刑（附加刑，可以独立适用也可以附加适用）。罚金数额根据犯罪情节决定；缴纳方式：一次或分期缴纳、强制缴纳、随时追缴、因灾祸等原因经裁定延期缴纳、酌情减少或者免除。没收财产是没收犯罪分子个人所有财产的一部或者全部：没收全部财产的，应当对犯罪分子个人及其扶养的家属保留必需的生活费用；不得没收属于犯罪分子家属所有或者应有的财产；没收财产以前犯罪分子所负的正当债务，需要以没收的财产偿还的，经债权人请求，应当偿还。附加刑的种类还有剥夺政治权利和驱逐出境（适用于犯罪的外国人）。" },
{ id: "XING-089", chapter: "拓展题库", type: "multi", difficulty: 3,
  stem: "关于假释，下列说法正确的有？",
  options: { A: "被判处有期徒刑的犯罪分子，执行原判刑期二分之一以上，可以适用假释", B: "对累犯以及因故意杀人、强奸、抢劫、绑架、放火、爆炸、投放危险物质或者有组织的暴力性犯罪被判处十年以上有期徒刑、无期徒刑的犯罪分子，不得假释", C: "假释考验期限内再犯新罪的，撤销假释，先减后并", D: "假释考验期满，就认为原判刑罚已经执行完毕" },
  answer: ["A", "B", "C", "D"],
  analysis: "A：应选。有期徒刑执行1/2以上、无期徒刑实际执行13年以上，认真遵守监规、接受教育改造、确有悔改表现、没有再犯罪危险的，可以假释。 B：应选。刑法第81条第2款的禁止假释情形。 C：应选。假释考验期内犯新罪，撤销假释，依照先减后并规则数罪并罚。 D：应选。假释考验期满没有法定撤销情形的，就认为原判刑罚已经执行完毕并公开宣告（与缓刑'不再执行'不同，故假释期满后5年内再犯罪可构成累犯）。 【考点】假释的条件：对象是被判处有期徒刑、无期徒刑的犯罪分子；执行刑期条件（有期徒刑1/2以上、无期徒刑实际执行13年以上，特殊情况经最高法核准可以不受限制）；实质条件（认真遵守监规，接受教育改造，确有悔改表现，没有再犯罪的危险）；禁止条件（累犯，以及因故意杀人、强奸、抢劫、绑架、放火、爆炸、投放危险物质或者有组织的暴力性犯罪被判处10年以上有期徒刑、无期徒刑的犯罪分子，不得假释）。考验期：有期徒刑为没有执行完毕的刑期，无期徒刑为10年。撤销事由：犯新罪（先减后并）、发现漏罪（先并后减）、违反监督管理规定（收监执行未执行完毕的刑罚）。假释期满视为原判刑罚执行完毕，这是与缓刑的重要区别。" },
{ id: "XING-090", chapter: "拓展题库", type: "single", difficulty: 3,
  stem: "甲公司财务人员乙利用管理公司资金的职务便利，挪用公司资金80万元用于个人炒股，超过3个月未还。乙构成？",
  options: { A: "挪用资金罪", B: "挪用公款罪", C: "职务侵占罪", D: "盗窃罪" },
  answer: ["A"],
  analysis: "A：正确。公司、企业或者其他单位的工作人员利用职务上的便利，挪用本单位资金归个人使用，数额较大、进行营利活动的，构成挪用资金罪。 B：错误。乙不是国家工作人员，公司也非国有单位从事公务情形，应定挪用资金罪。 C：错误。乙无非法占有目的（挪用意图归还），构成挪用而非侵占。 D：错误。乙利用的是职务便利而非单纯窃取，且无永久占有目的。 【考点】挪用资金罪：公司、企业或者其他单位的工作人员利用职务上的便利，挪用本单位资金归个人使用或者借贷给他人，数额较大、超过三个月未还的，或者虽未超过三个月，但数额较大、进行营利活动的，或者进行非法活动的，构成本罪。三种类型与挪用公款罪平行：非法活动型（门槛最低）、营利活动型（不要求超3个月）、一般用途型（数额较大+超3个月未还）。挪用本单位资金数额巨大的，或者数额较大不退还的，加重处罚。国有公司、企业或者其他国有单位中从事公务的人员和国有单位委派到非国有单位从事公务的人员挪用本单位资金的，依照挪用公款罪定罪处罚。" },
{ id: "XING-091", chapter: "拓展题库", type: "single", difficulty: 2,
  stem: "下列关于侮辱罪、诽谤罪的说法，正确的是？",
  options: { A: "侮辱罪、诽谤罪原则上告诉的才处理，但严重危害社会秩序和国家利益的除外", B: "诽谤罪要求捏造的事实必须完全虚构", C: "公然辱骂他人一律构成侮辱罪", D: "侮辱罪必须以捏造事实为手段" },
  answer: ["A"],
  analysis: "A：正确。刑法第246条：告诉才处理，但是严重危害社会秩序和国家利益的除外；通过信息网络实施且被害人提供证据确有困难的，法院可以要求公安机关提供协助。 B：错误。捏造事实包括部分虚构、篡改事实等足以贬损他人名誉的情形。 C：错误。须达到'情节严重'才构成犯罪，一般辱骂属治安处罚范畴。 D：错误。侮辱以暴力或者其他方法公然贬损人格（不需捏造事实）；捏造并散布虚假事实的是诽谤。 【考点】侮辱罪：以暴力或者其他方法公然侮辱他人，情节严重的行为——不要求捏造事实，核心是公然贬损他人人格尊严。诽谤罪：捏造事实诽谤他人（捏造并散布虚假事实），情节严重的行为。两罪均为告诉才处理的自诉犯罪，但严重危害社会秩序和国家利益的除外（如网络诽谤引发群体性事件、诽谤多人造成恶劣社会影响等，转为公诉）。网络诽谤的入罪标准：同一诽谤信息实际被点击、浏览次数达到5000次以上，或者被转发次数达到500次以上等。通过信息网络实施侮辱、诽谤，被害人向法院告诉但提供证据确有困难的，人民法院可以要求公安机关提供协助。" },
{ id: "XING-092", chapter: "拓展题库", type: "single", difficulty: 3,
  stem: "关于危险驾驶罪，下列行为不构成危险驾驶罪的是？",
  options: { A: "在道路上醉酒驾驶机动车", B: "在道路上驾驶机动车追逐竞驶，情节恶劣", C: "疲劳驾驶机动车", D: "从事校车业务，严重超过额定乘员载客" },
  answer: ["C"],
  analysis: "A：构成。醉驾（血液酒精含量≥80mg/100ml）是典型的危险驾驶行为。 B：构成。追逐竞驶情节恶劣构成危险驾驶罪。 C：不构成（应选）。危险驾驶罪限于四种法定行为：醉驾、追逐竞驶情节恶劣、校车或旅客运输严重超员超速、违规运输危险化学品危及公共安全。疲劳驾驶不在其列。 D：构成。校车业务或者旅客运输严重超员、严重超速的构成危险驾驶罪。 【考点】危险驾驶罪（刑法第133条之一）的四种法定行为类型：追逐竞驶，情节恶劣的；醉酒驾驶机动车的；从事校车业务或者旅客运输，严重超过额定乘员载客，或者严重超过规定时速行驶的；违反危险化学品安全管理规定运输危险化学品，危及公共安全的。本罪是抽象危险犯、故意犯罪，法定刑为拘役并处罚金（最轻的罪名之一）。机动车所有人、管理人对超员超速、违规运输危化品行为负有直接责任的，也依本罪处罚。有前述行为同时构成其他犯罪（交通肇事罪、以危险方法危害公共安全罪）的，依照处罚较重的规定定罪处罚。罪刑法定原则要求不得将疲劳驾驶、无证驾驶、吸毒后驾驶等未列举行为解释入罪。" },
{ id: "XING-093", chapter: "拓展题库", type: "single", difficulty: 3,
  stem: "甲医生值夜班时擅离职守外出会友，其间危重病人抢救无人处置死亡。经查若及时抢救病人极可能存活。甲的行为构成？",
  options: { A: "医疗事故罪", B: "过失致人死亡罪", C: "故意杀人罪（不作为）", D: "不构成犯罪" },
  answer: ["A"],
  analysis: "A：正确。医务人员由于严重不负责任，造成就诊人死亡或者严重损害就诊人身体健康的，构成医疗事故罪。擅离职守属严重不负责任的典型情形。 B：错误。医务人员在诊疗护理工作中的过失致死有专门罪名（特别法条优先）。 C：错误。甲对死亡结果是过失（疏忽或轻信），缺乏杀人的故意。 D：错误。严重不负责任致病人死亡已构成医疗事故罪。 【考点】医疗事故罪：医务人员由于严重不负责任，造成就诊人死亡或者严重损害就诊人身体健康的，处三年以下有期徒刑或者拘役。'严重不负责任'包括擅离职守、无正当理由拒绝救治、严重违反诊疗技术规范等。本罪是业务过失犯罪，与过失致人死亡罪是特别法与一般法的关系。区分医疗事故罪与医疗意外（医务人员已尽注意义务，因病情特殊或体质特殊发生的不良后果，不构成犯罪）、技术事故（因技术水平限制的失误，从宽把握）。非法行医罪：未取得医生执业资格的人非法行医，情节严重的构成，造成就诊人死亡的处十年以上有期徒刑。" },
{ id: "XING-094", chapter: "拓展题库", type: "single", difficulty: 3,
  stem: "甲伪造某市公安局的公文和印章，用于办理虚假户籍牟利。甲的行为构成？",
  options: { A: "伪造公司、企业、事业单位、人民团体印章罪", B: "伪造国家机关公文、印章罪", C: "招摇撞骗罪", D: "诈骗罪" },
  answer: ["B"],
  analysis: "A：错误。公安局是国家机关，应适用伪造国家机关公文、证件、印章罪。 B：正确。伪造、变造、买卖国家机关的公文、证件、印章的，构成伪造、变造、买卖国家机关公文、证件、印章罪。 C：错误。招摇撞骗罪是冒充国家机关工作人员招摇撞骗；本题是伪造公文印章行为本身。 D：错误。伪造公文印章有专门罪名；后续若骗取财物另论。 【考点】伪造、变造、买卖国家机关公文、证件、印章罪是行为犯，伪造行为完成即构成犯罪。对象是国家机关（各级权力机关、行政机关、司法机关、军事机关等）的公文、证件、印章。相关罪名辨析：伪造公司、企业、事业单位、人民团体印章罪（对象不同）；伪造、变造、买卖身份证件罪（居民身份证、护照、社会保障卡、驾驶证等依法可以用于证明身份的证件）；使用虚假身份证件、盗用身份证件罪（在依照国家规定应当提供身份证明的活动中使用伪造、变造的或者盗用他人的身份证件，情节严重）。伪造印章后又利用其实施诈骗等犯罪的，通常数罪并罚或依牵连犯从一重处理（视司法解释具体规定）。" },
{ id: "XING-095", chapter: "拓展题库", type: "multi", difficulty: 3,
  stem: "关于妨害公务罪与袭警罪，下列说法正确的有？",
  options: { A: "以暴力、威胁方法阻碍国家机关工作人员依法执行职务的，构成妨害公务罪", B: "暴力袭击正在依法执行职务的人民警察的，构成袭警罪", C: "使用枪支、管制刀具或者以驾驶机动车撞击等手段严重危及人民警察人身安全的，加重处罚", D: "对执行职务的警察进行辱骂但无暴力的，构成袭警罪" },
  answer: ["A", "B", "C"],
  analysis: "A：应选。妨害公务罪的基本构成，对象包括国家机关工作人员、人大代表（执行代表职务时）、红十字会工作人员（履行职责时）等。 B：应选。刑法修正案（十一）将袭警行为独立成罪：暴力袭击正在依法执行职务的人民警察的，处三年以下有期徒刑、拘役或者管制。 C：应选。袭警罪的加重情节，处三年以上七年以下有期徒刑。 D：不应选。袭警罪要求'暴力袭击'；单纯辱骂、拉扯轻微不构成本罪，可依治安管理处罚法处理。 【考点】妨害公务罪：以暴力、威胁方法阻碍国家机关工作人员依法执行职务。'依法执行职务'是前提，执行职务行为本身违法的，公民的抗拒不构成本罪。袭警罪（第277条第5款独立罪名）：暴力袭击正在依法执行职务的人民警察，基本刑三年以下；使用枪支、管制刀具，或者以驾驶机动车撞击等手段，严重危及其人身安全的，处三年以上七年以下。'暴力袭击'指突然性的直接人身攻击（打击、撞击、投掷等），对警用车辆、装备实施打砸的以妨害公务处理。袭警致警察重伤、死亡的，依故意伤害罪、故意杀人罪定罪处罚。" },
{ id: "XING-096", chapter: "拓展题库", type: "single", difficulty: 4,
  stem: "甲为公司利益向国家工作人员乙行贿100万元。案发前甲主动向监察机关交代了行贿事实。关于甲的处罚，下列说法正确的是？",
  options: { A: "行贿人在被追诉前主动交代行贿行为的，可以从轻或者减轻处罚；犯罪较轻的、对侦破重大案件起关键作用的或者有重大立功表现的，可以减轻或者免除处罚", B: "应当免除处罚", C: "主动交代不影响处罚", D: "以单位行贿论处则甲个人不受处罚" },
  answer: ["A"],
  analysis: "A：正确。刑法第390条第2款的特别宽宥规定。 B：错误。是'可以'从宽而非'应当免除'，且免除处罚有附加条件。 C：错误。被追诉前主动交代是行贿罪的法定从宽情节。 D：错误。单位行贿罪实行双罚制，直接责任人员仍要处罚。 【考点】行贿罪的特别从宽制度：行贿人在被追诉前主动交代行贿行为的，可以从轻或者减轻处罚；其中，犯罪较轻的，对侦破重大案件起关键作用的，或者有重大立功表现的，可以减轻或者免除处罚。'被追诉前'指检察机关立案前。因被勒索给予国家工作人员以财物，没有获得不正当利益的，不是行贿。介绍贿赂罪：向国家工作人员介绍贿赂，情节严重的构成，在被追诉前主动交代的可以减轻或者免除处罚。单位行贿罪与行贿罪的区分：为单位谋取不正当利益、行贿利益归单位的定单位行贿罪（双罚制）。对有影响力的人行贿罪：为谋取不正当利益，向国家工作人员的近亲属或者其他与其关系密切的人、离职的国家工作人员等行贿。" },
{ id: "XING-097", chapter: "拓展题库", type: "single", difficulty: 3,
  stem: "甲在证券交易中，作为内幕信息知情人员，在重大资产重组信息公开前买入该公司股票，获利300万元。甲构成？",
  options: { A: "内幕交易罪", B: "操纵证券市场罪", C: "利用未公开信息交易罪", D: "非法经营罪" },
  answer: ["A"],
  analysis: "A：正确。证券交易内幕信息的知情人员在涉及证券的发行、交易或者其他对证券价格有重大影响的信息尚未公开前，买入或者卖出该证券，情节严重的，构成内幕交易、泄露内幕信息罪。 B：错误。操纵市场是以连续交易、对倒、蛊惑交易等方式影响证券价格；利用内幕信息交易是内幕交易。 C：错误。该罪主体是金融机构从业人员利用因职务便利获取的内幕信息以外的其他未公开信息（如'老鼠仓'）；本题是内幕信息。 D：错误。证券犯罪有专门罪名体系。 【考点】内幕交易、泄露内幕信息罪：内幕信息的知情人员或者非法获取内幕信息的人员，在内幕信息尚未公开前，买入或者卖出该证券，或者从事与该内幕信息有关的期货交易，或者泄露该信息，或者明示、暗示他人从事上述交易活动，情节严重的构成。内幕信息指涉及公司的经营、财务或者对该公司证券的市场价格有重大影响的尚未公开的信息（重组、分红、业绩重大变化等）。相关罪名：利用未公开信息交易罪（金融机构从业人员'老鼠仓'行为）；操纵证券、期货市场罪（连续买卖、约定交易、自买自卖、蛊惑交易、抢帽子交易等手段）；违规披露、不披露重要信息罪（信息披露义务的公司向股东和社会公众提供虚假的或者隐瞒重要事实的财务会计报告）。" },
{ id: "XING-098", chapter: "拓展题库", type: "single", difficulty: 2,
  stem: "甲、乙因口角互殴，甲用拳头将乙鼻骨打成粉碎性骨折（经鉴定为轻伤二级）。甲构成？",
  options: { A: "故意伤害罪", B: "寻衅滋事罪", C: "不构成犯罪，属互殴", D: "过失致人重伤罪" },
  answer: ["A"],
  analysis: "A：正确。故意伤害他人身体达到轻伤以上程度的，构成故意伤害罪。 B：错误。因特定纠纷引发的互殴不属于无事生非的寻衅滋事。 C：错误。互殴不阻却故意伤害罪的成立，致人轻伤即构罪。 D：错误。甲有伤害故意且结果为轻伤，应定故意伤害罪。 【考点】故意伤害罪以造成轻伤以上后果为构罪门槛（轻微伤不构成本罪，属治安处罚范畴）。法定刑三档：致人轻伤的，三年以下有期徒刑、拘役或者管制；致人重伤的，三年以上十年以下有期徒刑；以特别残忍手段致人重伤造成严重残疾或者致人死亡的，十年以上有期徒刑、无期徒刑或者死刑。故意伤害致死是典型的结果加重犯，行为人对死亡结果持过失。互殴与正当防卫的区分是实务热点：因琐事发生争执，先动手且手段明显过激的一方为不法侵害人，还手一方符合防卫要件的可认定正当防卫（指导意见强调不能'谁受伤谁有理'）。伤情鉴定标准：轻伤二级以上进入刑事追诉。" },
{ id: "XING-099", chapter: "拓展题库", type: "multi", difficulty: 4,
  stem: "关于犯罪未遂与犯罪预备的区分标准'着手'，下列说法正确的有？",
  options: { A: "着手是实行行为的开始，通说认为是对法益产生现实、紧迫危险的行为开始时", B: "入户盗窃中，开始入户（如撬门）时即可认定盗窃的着手", C: "为杀人而购买毒药的行为属于着手", D: "投毒杀人中，将毒药投入被害人饭菜时是着手" },
  answer: ["A", "B", "D"],
  analysis: "A：应选。实质说（通说）以法益侵害的现实紧迫危险作为着手标准。 B：应选。入户盗窃场合，入户行为使户内财产法益面临紧迫危险，实务一般认定入户时着手。 C：不应选。购买毒药是准备工具，属于犯罪预备行为，尚未对生命法益产生紧迫危险。 D：应选。投放毒物使被害人生命面临现实紧迫危险，是杀人实行行为的开始。 【考点】犯罪预备与未遂以'着手'为界：为了犯罪，准备工具、制造条件的，是犯罪预备（可以比照既遂犯从轻、减轻处罚或者免除处罚）；已经着手实行犯罪，由于犯罪分子意志以外的原因而未得逞的，是犯罪未遂（可以比照既遂犯从轻或者减轻处罚）。着手的判断采实质标准：行为对刑法保护的法益产生了现实、紧迫、直接的危险。典型认定：杀人——举刀砍向、开枪瞄准、投毒于食物时着手；盗窃——接触、搜寻财物或入户时着手；诈骗——开始实施欺骗行为时着手；抢劫——开始实施暴力胁迫时着手。预备行为的常见形态：准备工具、调查踩点、尾随守候、诱骗被害人前往犯罪地点等。" },
{ id: "XING-100", chapter: "拓展题库", type: "single", difficulty: 3,
  stem: "甲潜入乙家盗窃，翻找许久只发现一个空保险柜，未窃得任何财物即离开。甲的行为属于？",
  options: { A: "盗窃罪未遂（不能犯未遂中的对象不能犯）", B: "犯罪中止", C: "犯罪预备", D: "无罪，因未取得财物" },
  answer: ["A"],
  analysis: "A：正确。甲已着手实行盗窃（入户翻找财物），因意志以外的原因（无财物可窃）未得逞，成立盗窃未遂。入户盗窃型不以数额为要件，未遂仍可追究。 B：错误。甲是'欲达目的而不能'——找不到财物才离开，非自动放弃。 C：错误。入户并翻找财物已属着手实行，超出预备阶段。 D：错误。入户盗窃系行为入罪类型，未遂形态依法可以追究刑事责任。 【考点】未遂犯的类型：能犯未遂与不能犯未遂（对象不能、手段不能）。我国通说认为不能犯未遂仍具有法益侵害的抽象危险，成立犯罪未遂（如误把白糖当砒霜投毒、盗窃时保险柜为空），迷信犯除外。对于未遂犯，可以比照既遂犯从轻或者减轻处罚。盗窃罪的行为类型：普通盗窃（数额较大）、多次盗窃（二年内三次以上）、入户盗窃、携带凶器盗窃、扒窃（公共场所窃取他人随身携带的财物）——后四种不要求数额较大。入户盗窃、扒窃未遂的，一般也应追究刑事责任（司法解释：以数额巨大的财物为盗窃目标的、以珍贵文物为目标的等未遂情形应追究）。" },
{ id: "XING-101", chapter: "拓展题库", type: "single", difficulty: 3,
  stem: "甲以勒索财物为目的，谎称已绑架乙的儿子（实际并未绑架），向乙勒索50万元。乙报警后甲被抓获。甲的行为构成？",
  options: { A: "绑架罪", B: "敲诈勒索罪（未遂）", C: "诈骗罪", D: "招摇撞骗罪" },
  answer: ["B"],
  analysis: "A：错误。甲并未实际绑架控制人质，缺乏绑架罪的实行行为。 B：正确。虚构绑架事实以恶害相通告勒索财物，是敲诈勒索；因被害人报警未取得财物，成立未遂。 C：错误。乙若交付财物是基于对儿子安危的恐惧而非单纯错误认识，符合敲诈勒索的构造（虚假恐吓也是恐吓）。 D：错误。甲未冒充国家机关工作人员。 【考点】敲诈勒索与诈骗的区分聚焦被害人交付财物的心理：基于恐惧心理交付→敲诈勒索；基于错误认识'自愿'交付→诈骗。虚构的恶害（谎称绑架、谎称掌握把柄）同样能引起恐惧，构成敲诈勒索；若被害人既有错误认识又有恐惧心理，通说按想象竞合或以主要作用的心理定罪。与绑架罪的区分：绑架罪须实际绑架、控制人质，向第三人勒索；未控制人质而谎称绑架的，只能成立敲诈勒索罪。敲诈勒索公私财物数额较大（2千至5千元以上）或者多次敲诈勒索的（二年内三次以上）构成犯罪。" },
{ id: "XING-102", chapter: "拓展题库", type: "multi", difficulty: 3,
  stem: "关于掩饰、隐瞒犯罪所得、犯罪所得收益罪，下列说法正确的有？",
  options: { A: "明知是犯罪所得而予以窝藏、转移、收购、代为销售的，构成本罪", B: "'明知'包括知道和应当知道，可以根据交易时间、地点、价格等异常情况综合推定", C: "上游犯罪尚未依法裁判，但查证属实的，不影响本罪的认定", D: "事前与盗窃犯通谋，事后代为销赃的，仍构成本罪" },
  answer: ["A", "B", "C"],
  analysis: "A：应选。第312条列举的行为方式：窝藏、转移、收购、代为销售或者以其他方法掩饰、隐瞒。 B：应选。以明显低于市场的价格收购、在非正常时间地点交易等可推定明知。 C：应选。上游犯罪事实成立即可，无需以生效判决为前提。 D：不应选。事前通谋的，以盗窃罪的共犯论处，不构成掩饰、隐瞒犯罪所得罪。 【考点】掩饰、隐瞒犯罪所得、犯罪所得收益罪（赃物犯罪）：明知是犯罪所得及其产生的收益而予以窝藏、转移、收购、代为销售或者以其他方法掩饰、隐瞒的行为。核心要点：本罪是事后帮助行为的独立犯罪，以无事前通谋为前提——事前通谋的以上游犯罪共犯论处；'明知'可以推定（交易价格明显异常、交易方式隐蔽、物品特征明显为赃物等）；上游犯罪查证属实即可，不要求已判决；本犯（上游犯罪人自己）处理自己赃物的行为属不可罚的事后行为（洗钱罪的自洗钱除外）。单位可以构成本罪。与洗钱罪的关系：七类上游犯罪的洗钱行为优先适用洗钱罪。" },
{ id: "XING-103", chapter: "拓展题库", type: "single", difficulty: 4,
  stem: "甲欲杀乙，用刀猛刺乙腹部后误以为乙已死亡，为毁尸灭迹将'尸体'扔入河中，乙实际死于溺水。关于甲的责任，下列说法正确的是？",
  options: { A: "故意杀人罪既遂", B: "故意杀人罪未遂与过失致人死亡罪并罚", C: "故意杀人罪未遂与（不可罚的）毁尸行为", D: "过失致人死亡罪" },
  answer: ["A"],
  analysis: "A：正确。这是因果关系错误中的事前故意（结果的推迟发生）情形：通说认为两个行为可视为一个整体的杀人行为，或者第一行为与死亡之间存在相当因果关系，行为人对因果历程的认识错误不重要，成立故意杀人罪既遂。 B：错误。此为少数说结论；通说认为因果历程的偏离不影响故意杀人既遂的成立。 C：错误。乙实际死亡且死亡与甲的整体行为有因果关系，不能仅评价为未遂。 D：错误。甲自始有杀人故意并实施杀人行为，死亡结果亦归属于其行为，成立故意杀人既遂。 【考点】事前故意（Weber的概括故意）是因果关系认识错误的经典类型：行为人误认为第一个行为已经造成结果，出于其他目的实施第二个行为，实际上是第二个行为导致预期的结果发生。通说（概括故意说/相当因果关系说）认为：只要第一行为与最终结果之间具有相当因果关系，因果历程的偏离在一般人预见可能的范围内，就应肯定故意犯罪既遂的成立。类似类型：结果的提前实现（构成要件的提前实现）——只有在第一行为已经着手的情况下才能认定既遂，如在准备阶段过失致死则成立预备与过失致死的并合。因果关系错误原则上不阻却故意，因为故意的认识内容不要求对因果历程的具体样态有精确认识。" },
{ id: "XING-104", chapter: "拓展题库", type: "single", difficulty: 3,
  stem: "关于拒不支付劳动报酬罪，下列说法正确的是？",
  options: { A: "以转移财产、逃匿等方法逃避支付劳动者的劳动报酬或者有能力支付而不支付，数额较大，经政府有关部门责令支付仍不支付的，构成本罪", B: "只要拖欠工资即构成犯罪", C: "单位不能构成本罪", D: "在提起公诉前支付劳动报酬的，一律不追究刑事责任" },
  answer: ["A"],
  analysis: "A：正确。本罪的完整构成要件，'经政府有关部门责令支付仍不支付'是构成要件要素（行政程序前置）。 B：错误。须以逃避支付或有能力而拒不支付+数额较大+经责令支付仍不支付为要件。 C：错误。单位可以构成本罪，实行双罚制。 D：错误。尚未造成严重后果，在提起公诉前支付劳动者的劳动报酬并依法承担相应赔偿责任的，可以减轻或者免除处罚——是从宽处罚而非一律不追究。 【考点】拒不支付劳动报酬罪（恶意欠薪罪）：以转移财产、逃匿等方法逃避支付劳动者的劳动报酬或者有能力支付而不支付劳动者的劳动报酬，数额较大，经政府有关部门责令支付仍不支付的，处三年以下有期徒刑或者拘役，并处或者单处罚金；造成严重后果的，处三年以上七年以下有期徒刑，并处罚金。特别从宽条款：尚未造成严重后果，在提起公诉前支付劳动者的劳动报酬，并依法承担相应赔偿责任的，可以减轻或者免除处罚。行政程序前置（责令支付）体现刑法的谦抑性，行为人逃匿无法送达责令支付文书的，依司法解释视为'经责令仍不支付'。" },
{ id: "XING-105", chapter: "拓展题库", type: "single", difficulty: 2,
  stem: "甲非法进入他人住宅，经住宅主人要求退出仍拒不退出。甲的行为构成？",
  options: { A: "非法侵入住宅罪", B: "寻衅滋事罪", C: "非法拘禁罪", D: "不构成犯罪" },
  answer: ["A"],
  analysis: "A：正确。非法侵入他人住宅或者经要求退出无正当理由拒不退出的，构成非法侵入住宅罪。 B：错误。侵入住宅有专门罪名。 C：错误。甲未剥夺他人人身自由。 D：错误。非法侵入住宅是刑法明文规定的犯罪，侵犯公民的住宅安宁权。 【考点】非法侵入住宅罪保护公民的住宅安宁与私生活领域，行为方式包括：未经同意非法进入他人住宅；经要求退出而无正当理由拒不退出。'住宅'指供他人日常生活的封闭空间，包括临时居住的场所。司法工作人员滥用职权犯本罪的，从重处罚。入户实施其他犯罪的处理：为实施盗窃、抢劫等犯罪而侵入住宅的，非法侵入住宅行为通常被后续犯罪吸收（如认定入户盗窃、入户抢劫），不再单独定罪；单纯的侵入住宅或者侵入后犯意未实施其他罪的，独立成罪。本罪与公民权利意识密切相关，'风能进、雨能进、国王不能进'即住宅权保护理念的体现。" },
{ id: "XING-106", chapter: "拓展题库", type: "multi", difficulty: 3,
  stem: "关于侵犯公民个人信息罪，下列说法正确的有？",
  options: { A: "违反国家有关规定，向他人出售或者提供公民个人信息，情节严重的，构成本罪", B: "将在履行职责或者提供服务过程中获得的公民个人信息出售或者提供给他人的，从重处罚", C: "窃取或者以其他方法非法获取公民个人信息的，同样构成本罪", D: "向特定个人提供其近亲属的行踪轨迹信息，无论用途如何均不构成犯罪" },
  answer: ["A", "B", "C"],
  analysis: "A：应选。本罪的基本行为方式之一。 B：应选。内部人员泄露信息从重处罚。 C：应选。非法获取型也是本罪行为方式。 D：不应选。非法提供行踪轨迹信息，被他人用于犯罪的，或明知他人利用信息实施犯罪仍提供的，入罪标准更低（50条即达'情节严重'）。 【考点】侵犯公民个人信息罪：违反国家有关规定，向他人出售或者提供公民个人信息，情节严重的；窃取或者以其他方法非法获取公民个人信息的，依照前款处罚。'公民个人信息'指以电子或者其他方式记录的能够单独或者与其他信息结合识别特定自然人身份或者反映特定自然人活动情况的各种信息。入罪的数量标准分级：行踪轨迹信息、通信内容、征信信息、财产信息50条以上；住宿信息、通信记录、健康生理信息、交易信息等500条以上；其他信息5000条以上；或违法所得5000元以上。特殊主体从重：将履职或提供服务中获得的信息出售、提供给他人的，从重处罚且数量标准减半。" },
{ id: "XING-107", chapter: "拓展题库", type: "single", difficulty: 3,
  stem: "甲因与乙有仇，向乙的鱼塘投放剧毒农药，毒死大量鱼类，造成损失30万元，同时污染了与鱼塘相通的灌溉水渠。对甲的行为定性，下列说法正确的是？",
  options: { A: "若毒物扩散足以危害公共安全，构成投放危险物质罪；仅损害特定财产的，构成故意毁坏财物罪", B: "一律构成投放危险物质罪", C: "一律构成故意毁坏财物罪", D: "构成污染环境罪" },
  answer: ["A"],
  analysis: "A：正确。区分关键是行为是否危及不特定或者多数人的生命、健康或重大公私财产安全：毒物流入公用水渠危及公共安全的定投放危险物质罪，封闭鱼塘内仅损害特定人财产的定故意毁坏财物罪。 B：错误。投放行为未危及公共安全的，不构成危害公共安全犯罪。 C：错误。若危害公共安全则应定投放危险物质罪。 D：错误。污染环境罪要求违反国家规定排放、倾倒、处置有害物质严重污染环境，本题主观是报复毁财或危害公共安全的故意，宜按前述罪名处理。 【考点】投放危险物质罪与故意毁坏财物罪（及故意杀人罪）的区分核心是公共安全标准：投放毒害性、放射性、传染病病原体等物质，危害公共安全（不特定或多数人的生命、健康或者重大公私财产安全）的，构成投放危险物质罪（危险犯，尚未造成严重后果处3-10年，造成严重后果处10年以上、无期或死刑）。向特定人的杯中投毒杀人是故意杀人罪；向封闭的私人鱼塘投毒毁财是故意毁坏财物罪；毒物可能扩散危及公众（投入水源、公共食堂饭菜）的是投放危险物质罪。判断时注意投放场所的开放性、毒物的扩散性、潜在被害对象的不特定性。" },
{ id: "XING-108", chapter: "拓展题库", type: "single", difficulty: 3,
  stem: "关于追诉时效，甲于2010年犯法定最高刑为10年有期徒刑的犯罪，追诉期限为多少年？",
  options: { A: "5年", B: "10年", C: "15年", D: "20年" },
  answer: ["C"],
  analysis: "A：错误。法定最高刑不满5年有期徒刑的，追诉时效为5年。 B：错误。法定最高刑为5年以上不满10年有期徒刑的，经过10年。 C：正确。法定最高刑为10年以上有期徒刑的，经过15年不再追诉。'10年以上'包括本数10年。 D：错误。法定最高刑为无期徒刑、死刑的，经过20年；如果20年以后认为必须追诉的，须报请最高人民检察院核准。 【考点】追诉时效期限按法定最高刑分档：法定最高刑不满5年有期徒刑的，经过5年；5年以上不满10年的，经过10年；10年以上有期徒刑的，经过15年；无期徒刑、死刑的，经过20年，20年后认为必须追诉的须报请最高人民检察院核准。时效计算：从犯罪之日起计算；犯罪行为有连续或者继续状态的，从犯罪行为终了之日起计算。时效中断：在追诉期限以内又犯罪的，前罪追诉的期限从犯后罪之日起计算。时效延长（不受追诉期限限制）：在司法机关立案侦查或者法院受理案件以后，逃避侦查或者审判的；被害人在追诉期限内提出控告，应当立案而不予立案的。" },
{ id: "XING-109", chapter: "拓展题库", type: "single", difficulty: 2,
  stem: "甲组织、领导以'消费返利'为名、要求参加者缴纳费用并按层级发展人员的传销活动，骗取财物。甲构成？",
  options: { A: "组织、领导传销活动罪", B: "非法经营罪", C: "集资诈骗罪", D: "诈骗罪" },
  answer: ["A"],
  analysis: "A：正确。组织、领导以推销商品、提供服务等经营活动为名，要求参加者以缴纳费用或者购买商品、服务等方式获得加入资格，并按照一定顺序组成层级，直接或者间接以发展人员的数量作为计酬或者返利依据，引诱、胁迫参加者继续发展他人参加，骗取财物，扰乱经济社会秩序的传销活动的，构成本罪。 B：错误。传销组织行为有专门罪名。 C：错误。本题是拉人头缴费的传销模式，非面向社会公众吸收资金的集资诈骗。 D：错误。组织、领导传销活动罪是特别规定，优先适用。 【考点】组织、领导传销活动罪的构成要点：以推销商品、提供服务等经营活动为名；要求参加者缴纳费用或者购买商品服务获得加入资格；按照一定顺序组成层级（三级以上且30人以上追究组织者领导者）；直接或间接以发展人员数量作为计酬或返利依据（'拉人头'）；骗取财物。处罚对象限于组织者、领导者（发起、策划、操纵人员，管理、协调人员，宣传、培训人员等），一般参加者不构成本罪。'团队计酬'式单纯以销售业绩计酬的经营性传销不作为犯罪处理。传销活动中实施诈骗、非法拘禁、故意伤害等行为的，数罪并罚或依想象竞合处理。" },
{ id: "XING-110", chapter: "拓展题库", type: "multi", difficulty: 4,
  stem: "关于结果加重犯，下列说法正确的有？",
  options: { A: "结果加重犯的成立要求基本犯罪行为与加重结果之间具有直接因果关系", B: "行为人对加重结果至少有过失", C: "故意伤害致人死亡、抢劫致人死亡、强奸致人死亡都是结果加重犯", D: "结果加重犯存在未遂形态时，一律按基本犯处理" },
  answer: ["A", "B", "C"],
  analysis: "A：应选。加重结果必须是基本行为固有危险的现实化，介入异常因素中断因果关系的不成立结果加重犯。 B：应选。对加重结果无任何罪过（意外事件）的，不成立结果加重犯（责任主义要求）。 C：应选。这些都是刑法明文规定加重法定刑的结果加重犯。 D：不应选。基本犯既遂但加重结果未发生的按基本犯处理；基本犯未遂但加重结果发生的（如强奸未遂致人死亡），仍适用加重法定刑并可适用未遂犯规定，学理与实务均不'一律按基本犯'处理。 【考点】结果加重犯是实施基本犯罪行为、发生了基本构成要件以外的加重结果，刑法规定加重法定刑的犯罪形态。成立条件：实施基本犯罪行为并发生加重结果；基本行为与加重结果之间有直接因果关系（危险的直接现实化，如被害人为逃避强奸跳楼死亡可归责，但已脱离控制数日后自杀的一般不归责）；行为人对加重结果至少有过失；刑法就加重结果规定了加重法定刑。常见结果加重犯：故意伤害致死、抢劫致人重伤死亡、强奸致人重伤死亡、非法拘禁致人重伤死亡、放火决水爆炸致人重伤死亡、拐卖妇女儿童造成被害人或其亲属重伤死亡等。转化犯（非法拘禁使用暴力致人伤残死亡转化为故意伤害、故意杀人）与结果加重犯应注意区分。" },
{ id: "XING-111", chapter: "拓展题库", type: "indeterminate", difficulty: 4,
  stem: "甲系某国有银行支行行长。储户乙将500万元存入该支行，甲利用职务便利，私刻公章伪造存单交给乙，将该500万元转入自己控制的账户用于偿还个人赌债，且无归还能力和归还意图。下列说法正确的是？",
  options: { A: "甲构成贪污罪", B: "甲构成挪用公款罪", C: "若甲是非国有商业银行的支行行长（非国家工作人员），同样行为构成职务侵占罪", D: "乙的存款损失只能由乙自行承担" },
  answer: ["A", "C"],
  analysis: "A：应选。甲是国有银行中从事公务的国家工作人员，利用职务便利，以骗取手段非法占有单位管理中的客户资金（公共财物），具有非法占有目的（用于还赌债且无归还意图），构成贪污罪。 B：不应选。挪用公款罪以准备归还为前提；甲无归还意图和能力，且用于偿还赌债后资金灭失，应认定非法占有目的，定贪污罪。 C：应选。主体身份变化导致罪名平移：非国家工作人员利用职务便利非法占有本单位财物（含单位管理中的客户资金），构成职务侵占罪。 D：不应选。储户在银行柜台正常办理存款手续的，存款关系成立，损失由银行承担后再向甲追偿；乙作为被害人的民事权益受法律保护。 【考点】金融机构工作人员侵吞客户资金的定性：客户资金进入银行管理体系后属于单位占有、管理的财物，国家工作人员利用职务便利非法占有的构成贪污罪，非国家工作人员构成职务侵占罪。贪污与挪用的界分看非法占有目的：用于赌博、挥霍等致使资金无法归还，或者携款潜逃、平账掩饰的，认定非法占有目的定贪污罪；临时挪用、准备归还的定挪用公款罪。贪污受贿的定罪量刑标准：数额较大（3万元以上）、数额巨大（20万元以上）、数额特别巨大（300万元以上），并结合情节。贪污数额特别巨大并使国家和人民利益遭受特别重大损失的，可判处无期徒刑或死刑（终身监禁制度适用于贪污受贿被判死缓的重大犯罪分子）。" },
{ id: "XING-112", chapter: "拓展题库", type: "indeterminate", difficulty: 3,
  stem: "关于禁止令与职业禁止，下列说法正确的是？",
  options: { A: "对判处管制、宣告缓刑的犯罪分子，法院可以根据犯罪情况，同时禁止其在管制执行期间、缓刑考验期内从事特定活动，进入特定区域、场所，接触特定的人", B: "因利用职业便利实施犯罪被判处刑罚的，法院可以禁止其自刑罚执行完毕之日或者假释之日起从事相关职业，期限为三年至五年", C: "违反职业禁止决定，情节严重的，构成拒不执行判决、裁定罪", D: "其他法律、行政法规对从事相关职业另有禁止或者限制性规定的，法院的职业禁止决定优先于该规定适用" },
  answer: ["A", "B", "C"],
  analysis: "A：应选。这是禁止令制度（刑法第38条、第72条）。 B：应选。职业禁止制度（刑法第37条之一），适用于利用职业便利实施犯罪或者实施违背职业要求的特定义务的犯罪。 C：应选。刑法第37条之一第2款明确规定。 D：不应选。其他法律、行政法规另有规定的，从其规定（如证券法、公司法对特定犯罪人的任职终身或长期限制）。 【考点】禁止令与职业禁止是预防再犯罪的保安处分性质措施。禁止令：附着于管制和缓刑，内容是禁止从事特定活动、进入特定区域场所、接触特定的人，由社区矫正机构执行，违反禁止令尚不属情节严重的治安处罚，缓刑犯违反情节严重的撤销缓刑。职业禁止：因利用职业便利实施犯罪，或者实施违背职业要求的特定义务的犯罪被判处刑罚的，法院可以根据犯罪情况和预防再犯罪的需要，禁止其自刑罚执行完毕之日或者假释之日起从事相关职业，期限三年至五年；违反的由公安机关处罚，情节严重的构成拒不执行判决、裁定罪；其他法律、行政法规另有禁止或限制性规定的从其规定。" },
{ id: "XING-113", chapter: "拓展题库", type: "multi", difficulty: 3,
  stem: "关于减刑，下列说法正确的有？",
  options: { A: "被判处管制、拘役、有期徒刑、无期徒刑的犯罪分子，在执行期间认真遵守监规、接受教育改造、确有悔改表现或者有立功表现的，可以减刑", B: "有阻止他人重大犯罪活动等重大立功表现之一的，应当减刑", C: "减刑以后实际执行的刑期，判处有期徒刑的不能少于原判刑期的二分之一", D: "减刑由执行机关直接决定" },
  answer: ["A", "B", "C"],
  analysis: "A：应选。'可以减刑'的条件。 B：应选。有重大立功表现（阻止他人重大犯罪活动；检举监狱内外重大犯罪活动查证属实；有发明创造或者重大技术革新；舍己救人；抗御自然灾害或排除重大事故中有突出表现；对国家和社会有其他重大贡献）的，应当减刑。 C：应选。管制、拘役、有期徒刑减刑后实际执行不能少于原判刑期的1/2；无期徒刑的不能少于13年。 D：不应选。减刑由执行机关向中级以上人民法院提出减刑建议书，由法院组成合议庭审理裁定，非经法定程序不得减刑。 【考点】减刑的适用对象是被判处管制、拘役、有期徒刑、无期徒刑的犯罪分子（所有刑种中的主刑执行者）。条件分'可以减刑'（认真遵守监规、接受教育改造、确有悔改表现或者有立功表现）与'应当减刑'（有重大立功表现的六种情形）。减刑的限度：实际执行刑期，管制、拘役、有期徒刑不能少于原判刑期的1/2；无期徒刑不能少于13年；死缓限制减刑的，缓期执行期满后依法减为无期徒刑的不能少于25年，减为25年有期徒刑的不能少于20年。程序：执行机关提出建议书→中级以上人民法院合议庭审理→裁定。人民检察院对减刑、假释活动实行监督。" },
{ id: "XING-114", chapter: "拓展题库", type: "single", difficulty: 3,
  stem: "甲用假币在乙的商店购买价值2000元的商品。甲使用假币总面额2万元。甲的行为构成？",
  options: { A: "使用假币罪", B: "诈骗罪", C: "使用假币罪与诈骗罪并罚", D: "不构成犯罪" },
  answer: ["A"],
  analysis: "A：正确。明知是伪造的货币而使用，数额较大（总面额4000元以上）的，构成持有、使用假币罪。使用行为针对不知情的相对方。 B：错误。使用假币骗取财物的行为被使用假币罪特别条款吸收，依特别法优先原则定使用假币罪。 C：错误。一行为触犯两罪名属法条竞合，不并罚。 D：错误。使用假币总面额2万元已达'数额较大'标准。 【考点】持有、使用假币罪：明知是伪造的货币而持有、使用，数额较大的行为（总面额4000元以上为数额较大，5万元以上巨大，20万元以上特别巨大）。'使用'指将假币作为真币投入流通（购物、还债、赌博、缴纳费用等）。使用假币与诈骗罪的关系是法条竞合，使用假币罪是特别规定优先适用。相关罪数问题：出售假币同时又使用的，并罚或从一重（依情形）；伪造货币又使用自己伪造的货币的，以伪造货币罪定罪从重处罚。'明知'的推定：无正当理由持有大量假币、以明显低价购入'货币'等。银行工作人员利用职务便利以假币换取真币的，构成金融工作人员以假币换取货币罪（更重）。" },
{ id: "XING-115", chapter: "拓展题库", type: "single", difficulty: 2,
  stem: "甲因琐事在餐厅无故殴打素不相识的顾客乙（致轻微伤），又随意砸毁餐厅餐具，情节恶劣。甲构成？",
  options: { A: "寻衅滋事罪", B: "故意伤害罪", C: "故意毁坏财物罪", D: "不构成犯罪" },
  answer: ["A"],
  analysis: "A：正确。随意殴打他人情节恶劣、任意损毁公私财物情节严重的，无事生非、借故生非型行为构成寻衅滋事罪。 B：错误。轻微伤未达故意伤害罪的轻伤门槛；随意殴打型寻衅滋事不要求轻伤。 C：错误。任意损毁财物是寻衅滋事的行为方式之一，本题整体评价为寻衅滋事罪。 D：错误。无事生非随意殴打他人情节恶劣即构成寻衅滋事罪。 【考点】寻衅滋事罪的四种行为类型：随意殴打他人，情节恶劣的；追逐、拦截、辱骂、恐吓他人，情节恶劣的；强拿硬要或者任意损毁、占用公私财物，情节严重的；在公共场所起哄闹事，造成公共场所秩序严重混乱的。本罪的本质特征是无事生非、借故生非，寻求刺激、发泄情绪、逞强耍横。与故意伤害罪的区分：殴打的'随意性'（对象、起因的随意）；致人轻伤的可能同时构成故意伤害罪，从一重处断；致人重伤、死亡的定故意伤害罪、故意杀人罪。纠集他人多次实施寻衅滋事行为，严重破坏社会秩序的，处五年以上十年以下有期徒刑，可以并处罚金。" },
{ id: "XING-116", chapter: "拓展题库", type: "single", difficulty: 3,
  stem: "甲多次以叫外卖不给钱、吃霸王餐方式强拿硬要，并纠集乙、丙形成较为固定的犯罪组织，通过暴力、威胁手段在某集贸市场强收'保护费'，称霸一方，严重破坏当地经济、社会生活秩序。该组织的性质是？",
  options: { A: "黑社会性质组织", B: "恶势力团伙但不构成犯罪组织", C: "一般共同犯罪", D: "犯罪集团即等同于黑社会性质组织" },
  answer: ["A"],
  analysis: "A：正确。具备组织特征（较稳定、人数较多、有明确组织者）、经济特征（有组织地攫取经济利益）、行为特征（暴力威胁手段多次违法犯罪）、危害性特征（称霸一方，严重破坏经济社会生活秩序）的，认定为黑社会性质组织。 B：错误。题干已具备黑社会性质组织的四个特征；恶势力是尚未形成黑社会性质组织的过渡形态。 C：错误。有固定组织、持续实施有组织犯罪并形成非法控制的，超出一般共犯范畴。 D：错误。黑社会性质组织是犯罪集团的特殊形态，须同时具备四特征，普通犯罪集团不当然构成。 【考点】黑社会性质组织的四个特征（刑法第294条）：组织特征（形成较稳定的犯罪组织，人数较多，有明确的组织者、领导者，骨干成员基本固定）；经济特征（有组织地通过违法犯罪活动或者其他手段获取经济利益，具有一定的经济实力，以支持该组织的活动）；行为特征（以暴力、威胁或者其他手段，有组织地多次进行违法犯罪活动，为非作恶，欺压、残害群众）；危害性特征/非法控制特征（通过实施违法犯罪活动，或者利用国家工作人员的包庇或者纵容，称霸一方，在一定区域或者行业内，形成非法控制或者重大影响，严重破坏经济、社会生活秩序）。组织、领导、参加黑社会性质组织又有其他犯罪行为的，数罪并罚。国家机关工作人员包庇、纵容黑社会性质组织的，构成包庇、纵容黑社会性质组织罪。" },
{ id: "XING-117", chapter: "拓展题库", type: "single", difficulty: 3,
  stem: "甲见义勇为追赶抢夺犯乙，将乙扑倒时致乙小腿骨折（轻伤）。关于甲的行为，下列说法正确的是？",
  options: { A: "构成故意伤害罪", B: "属于正当防卫（或依法扭送的正当行为），不负刑事责任", C: "构成过失致人重伤罪", D: "甲应与乙分担损失" },
  answer: ["B"],
  analysis: "A：错误。为制止正在进行的不法侵害（抢夺后逃跑仍属侵害延续）而采取的合理强制行为，属正当防卫（或法令行为——公民扭送），阻却违法。 B：正确。对正在进行的抢夺犯罪实施防卫、扭送中使用必要强制力，未明显超过必要限度的，不负刑事责任。刑诉法规定对正在实行犯罪或犯罪后即时被发觉的人，任何公民都可以立即扭送司法机关。 C：错误。乙仅轻伤，且甲的行为具有违法阻却事由。 D：错误。防卫行为造成不法侵害人损害且未过当的，不承担责任。 【考点】公民扭送是法令行为（正当行为）：对正在实行犯罪或者在犯罪后即时被发觉的、通缉在案的、越狱逃跑的、正在被追捕的人，任何公民都可以立即扭送公安机关、人民检察院或者人民法院处理。扭送中为制服反抗、防止逃跑而使用必要强制力，造成合理限度内损害的，不负刑事责任。财产犯罪的正当防卫时间：抢夺、盗窃既遂后，在现场以及被及时追捕的过程中，视为不法侵害仍在进行，可以实施防卫（财物尚可挽回）。见义勇为致不法侵害人损害的民法保护：因保护他人民事权益使自己受到损害的，由侵权人承担责任，受益人可以给予适当补偿；因自愿实施紧急救助行为造成受助人损害的，救助人不承担民事责任（好人条款）。" }
]);
